// @particles 5000

// Rain — the same rain, drawn as geometry.
//
// The fullscreen version drew two flat CURTAINS, one behind the cast and one in
// front, and feathered the far one against the silhouette by hand. That was the
// only way to fake depth from a screen-space effect. These drops are real points
// in the scene, depth-tested like anything else, so a drop passes behind her
// shoulder and in front of her hand in the same frame with nothing to tune.
//
// The volume is FIXED TO THE STAGE, not to the camera.
//
// Following the eye seemed right — weather is everywhere, so keep it where you
// are looking — but it makes the weather a property of the camera rather than of
// the scene, and a camera VMD is the case that proves it wrong: a VMD dollies and
// cuts, and the whole field would lurch after it on every cut. A stage that snows
// is a stage that snows regardless of where you stand to watch it.
//
// The cost is honest: fly the camera outside CENTER ± AREA and the weather is
// behind you. MMD scenes are staged around the origin, so that is a corner rather
// than the common case, and AREA is the dial if a scene needs a bigger stage.

// Tunables.
const COLOR = vec3f(0.82, 0.90, 1.0);
const INTENSITY = 2.4;   // HDR: particles draw before tone mapping, so white needs headroom
const FALL = 24.0;       // metres per second — rain is much faster than it looks
const SLANT = 0.11;      // wind, as a fraction of fall speed
const CENTER = vec3f(0.0, 0.0, 0.0);   // the stage the weather falls on
const AREA = 34.0;       // half-width of the volume
const TOP = 44.0;        // drops enter well above the frame, not just off the top
const WIDTH = 0.009;     // a drop's thickness
const LENGTH = 18.0;     // and how many times longer than it is wide
const HEAD = 0.55;       // how much brighter the leading end is

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let r = rzHash13(seed + f32(id) * 0.0131);
  let r2 = rzHash13(seed * 2.13 + f32(id) * 0.0357);
  p.pos = vec3f(CENTER.x + (r.x - 0.5) * AREA * 2.0, r.y * TOP, CENTER.z + (r.z - 0.5) * AREA * 2.0);
  let speed = FALL * mix(0.85, 1.2, r2.x);
  p.vel = vec3f(SLANT * speed, -speed, SLANT * 0.4 * speed);
  p.size = WIDTH * mix(0.75, 1.35, r2.y);
  // The engine orients a stretched quad along the drop's SCREEN velocity, so a
  // streak stays a streak from any angle instead of becoming a smear from above.
  p.stretch = LENGTH * mix(0.8, 1.25, r2.z);
  // Long enough never to expire: these drops WRAP rather than die (see step), so
  // the pool is a continuous curtain instead of one that thins and refills.
  p.life = 1.0e9;
  p.seed = seed + f32(id) * 0.0131;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  q.pos = q.pos + q.vel * dt;
  // WRAPPED, not recycled.
  //
  // Recycling through the pool was wrong twice. A respawn lands at a random
  // height, so drops popped into existence in mid-air; and staggering their age
  // to avoid that put them at random points in a fade curve, so a share of the
  // curtain was always fading out — which is what made the rain intermittent.
  // A drop that reappears at the top is seamless by construction.
  // TOROIDAL in x/z as well as y.
  //
  // Wrapping only at the floor meant the volume moved with the camera but its
  // contents did not: orbiting left the old field draining where it was while a
  // new one filled in slowly, a fall-time behind. Folding x and z about the
  // centre too means a flake that leaves one side re-enters on the other in the
  // SAME frame, so the field is always centred and never has to refill. The
  // seam sits AREA away, off to the side and far from what you are looking at.
  let span = AREA * 2.0;
  let rx = q.pos.x - CENTER.x;
  let rz = q.pos.z - CENTER.z;
  q.pos.x = CENTER.x + rx - span * floor(rx / span + 0.5);
  q.pos.z = CENTER.z + rz - span * floor(rz / span + 0.5);
  // And over the top at the floor, in a freshly chosen column so the same line
  // does not fall forever.
  if (q.pos.y < 0.0) {
    let h = rzHash13(q.seed + rzTime() * 0.37);
    q.pos = vec3f(CENTER.x + (h.x - 0.5) * span, TOP, CENTER.z + (h.z - 0.5) * span);
  }
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  // Across the drop: soft, so it is a filament rather than a hard bar.
  let across = rzFalloff(abs(q.x), 1.0);
  // Along it: taper both ends, and weight the leading one — a falling drop is
  // brightest where it is going, which is what reads as speed.
  let along = smoothstep(1.0, 0.55, abs(q.y));
  let head = mix(1.0 - HEAD, 1.0, clamp(q.y * 0.5 + 0.5, 0.0, 1.0));
  // No lifetime fade: a wrapped drop never dies, so there is nothing to fade —
  // and fading a fraction of them at any moment is exactly what made the
  // previous version flicker.
  return vec4f(COLOR * INTENSITY * head, across * along);
}

// @fullres — this effect draws scanlines and glyph edges: sub-pixel detail the half-res field
// pass cannot carry, so it opts out and pays its own full price.
// Tunables — edit and ⌘⏎.
const NEON_COLOR = vec3f(0.96, 0.45, 0.71);  // tube color (brand pink)
const NEON_COLOR_B = vec3f(0.45, 0.65, 0.98); // second hue the shimmer travels to
const GLOW = 0.8;                            // halo strength
const FLICKER = 0.1;                         // 0 = steady sign
const TEXT_SCALE = 0.075;                    // sign size on screen
const POS_Y = 0.24;                          // height above center

fn sdSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h);
}

// "REZE DESIGN" as 40 pre-baked segments (glyph boxes 0..0.9 × 0..1, advance 1.2, word gap
fn sdText(p: vec2f) -> f32 {
  // Coarse reject: pixels far from the sign's bounding box skip the letters entirely (the halo
  let toBox = vec2f(max(abs(p.x - 6.20) - 6.20, 0.0), max(abs(p.y - 0.5) - 0.5, 0.0));
  let boxD = length(toBox);
  if (boxD > 1.0) { return boxD; }
  var d = 1e5;
  d = min(d, sdSegment(p, vec2f(0.0, 0), vec2f(0.0, 1)));
  d = min(d, sdSegment(p, vec2f(0.0, 1), vec2f(0.8, 1)));
  d = min(d, sdSegment(p, vec2f(0.8, 1), vec2f(0.8, 0.5)));
  d = min(d, sdSegment(p, vec2f(0.8, 0.5), vec2f(0.0, 0.5)));
  d = min(d, sdSegment(p, vec2f(0.4, 0.5), vec2f(0.9, 0)));
  d = min(d, sdSegment(p, vec2f(1.2, 0), vec2f(1.2, 1)));
  d = min(d, sdSegment(p, vec2f(1.2, 1), vec2f(2.1, 1)));
  d = min(d, sdSegment(p, vec2f(1.2, 0.5), vec2f(1.9, 0.5)));
  d = min(d, sdSegment(p, vec2f(1.2, 0), vec2f(2.1, 0)));
  d = min(d, sdSegment(p, vec2f(2.4, 1), vec2f(3.3, 1)));
  d = min(d, sdSegment(p, vec2f(3.3, 1), vec2f(2.4, 0)));
  d = min(d, sdSegment(p, vec2f(2.4, 0), vec2f(3.3, 0)));
  d = min(d, sdSegment(p, vec2f(3.6, 0), vec2f(3.6, 1)));
  d = min(d, sdSegment(p, vec2f(3.6, 1), vec2f(4.5, 1)));
  d = min(d, sdSegment(p, vec2f(3.6, 0.5), vec2f(4.3, 0.5)));
  d = min(d, sdSegment(p, vec2f(3.6, 0), vec2f(4.5, 0)));
  d = min(d, sdSegment(p, vec2f(5.5, 0), vec2f(5.5, 1)));
  d = min(d, sdSegment(p, vec2f(5.5, 1), vec2f(6.15, 1)));
  d = min(d, sdSegment(p, vec2f(6.15, 1), vec2f(6.4, 0.75)));
  d = min(d, sdSegment(p, vec2f(6.4, 0.75), vec2f(6.4, 0.25)));
  d = min(d, sdSegment(p, vec2f(6.4, 0.25), vec2f(6.15, 0)));
  d = min(d, sdSegment(p, vec2f(6.15, 0), vec2f(5.5, 0)));
  d = min(d, sdSegment(p, vec2f(6.7, 0), vec2f(6.7, 1)));
  d = min(d, sdSegment(p, vec2f(6.7, 1), vec2f(7.6, 1)));
  d = min(d, sdSegment(p, vec2f(6.7, 0.5), vec2f(7.4, 0.5)));
  d = min(d, sdSegment(p, vec2f(6.7, 0), vec2f(7.6, 0)));
  d = min(d, sdSegment(p, vec2f(8.8, 1), vec2f(7.9, 1)));
  d = min(d, sdSegment(p, vec2f(7.9, 1), vec2f(7.9, 0.5)));
  d = min(d, sdSegment(p, vec2f(7.9, 0.5), vec2f(8.8, 0.5)));
  d = min(d, sdSegment(p, vec2f(8.8, 0.5), vec2f(8.8, 0)));
  d = min(d, sdSegment(p, vec2f(8.8, 0), vec2f(7.9, 0)));
  d = min(d, sdSegment(p, vec2f(9.55, 0), vec2f(9.55, 1)));
  d = min(d, sdSegment(p, vec2f(11.2, 1), vec2f(10.3, 1)));
  d = min(d, sdSegment(p, vec2f(10.3, 1), vec2f(10.3, 0)));
  d = min(d, sdSegment(p, vec2f(10.3, 0), vec2f(11.2, 0)));
  d = min(d, sdSegment(p, vec2f(11.2, 0), vec2f(11.2, 0.45)));
  d = min(d, sdSegment(p, vec2f(11.2, 0.45), vec2f(10.8, 0.45)));
  d = min(d, sdSegment(p, vec2f(11.5, 0), vec2f(11.5, 1)));
  d = min(d, sdSegment(p, vec2f(11.5, 1), vec2f(12.4, 0)));
  d = min(d, sdSegment(p, vec2f(12.4, 0), vec2f(12.4, 1)));
  return d;
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let res = bgResolution();
  var p = (uv - 0.5) * vec2f(res.x / res.y, 1.0);
  p.y -= POS_Y;
  // The sign breathes and sways — quiet motion that says "live shader", not GIF.
  let wobble = 0.05 * sin(time * 0.9);
  let breathe = 1.0 + 0.05 * sin(time * 1.7);
  let c = cos(wobble);
  let si = sin(wobble);
  p = mat2x2f(c, -si, si, c) * p;
  // Screen space → text space (centered).
  let tp = p / (TEXT_SCALE * breathe) + vec2f(12.4 * 0.5, 0.5);
  let d = sdText(vec2f(tp.x, tp.y));

  // Neon = crisp tube + inner hot line + tight halo.
  let aa = fwidth(d) * 1.5;
  let tube = 1.0 - smoothstep(0.06 - aa, 0.06 + aa, d);
  let hot = 1.0 - smoothstep(0.02 - aa, 0.02 + aa, d);
  let core = tube * 0.75 + hot * 0.45;
  let halo = exp(-d * 5.0) * GLOW;
  // Gentle electrical shimmer (two incommensurate frequencies, shallow depth).
  let flicker = 1.0 - FLICKER * (0.5 + 0.5 * sin(time * 7.3) * sin(time * 3.1));
  let s = (core + halo) * flicker;

  // A hue gradient travels along the sign — the "this is a shader" tell.
  let hue = mix(NEON_COLOR, NEON_COLOR_B, 0.5 + 0.5 * sin(time * 1.1 + tp.x * 0.45));
  let color = hue + vec3f(0.35) * core; // core burns toward white
  return vec4f(clamp(color, vec3f(0.0), vec3f(1.0)), clamp(s, 0.0, 1.0));
}

// Tunables — edit a value and hit ⌘⏎ to see it live.
const TINT = vec3f(1.0, 0.96, 0.88);  // star color
const DENSITY = 0.5;                  // 0..1 — how crowded the sky is
const TWINKLE = 0.5;                  // 0..1 — flicker speed
const INTENSITY = 1.2;                // overall brightness

fn bgHash2(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

fn starLayer(sph: vec2f, scale: f32, thresh: f32, time: f32, speed: f32) -> f32 {
  let cell = floor(sph * scale);
  let h = bgHash2(cell);
  // Star sits at a hashed point inside its cell — kills the grid look.
  let local = fract(sph * scale) - (0.15 + 0.7 * h);
  let d = length(local);
  let bright = bgHash2(cell + 7.31).x;
  if (bright < thresh) { return 0.0; }
  // Per-star period from its own hash: some stars breathe over seconds, some blink quickly
  let period = 0.25 + 2.75 * bgHash2(cell + 31.7).y;
  let tw = 0.55 + 0.45 * sin(time * speed * period + h.x * 40.0);
  let size = (bright - thresh) / (1.0 - thresh);
  // Tight core + faint halo — a hard point of light, not a blurry blob.
  let r = 0.03 + 0.045 * size;
  let core = smoothstep(r, r * 0.25, d);
  let halo = smoothstep(r * 4.0, r, d) * 0.18;
  return (core + halo) * tw * (0.45 + 0.75 * size);
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  let d = normalize(ray);
  // Latitude/longitude projection
  let sph = vec2f(atan2(d.x, d.z) * 1.2, asin(clamp(d.y, -1.0, 1.0)) * 1.5);
  // Denser = MORE stars, not smaller ones (sizes untouched)
  let dens = mix(0.95, 0.82, clamp(DENSITY, 0.0, 1.0));
  var s = starLayer(sph, 30.0, dens, time, TWINKLE * 1.6);
  // Faint dust layer: denser, smaller, slower.
  s += 0.4 * starLayer(sph + 3.7, 70.0, mix(0.985, 0.9, clamp(DENSITY, 0.0, 1.0)), time, TWINKLE * 0.9);
  let a = clamp(s * INTENSITY, 0.0, 1.0);
  // Straight alpha — the engine's over-composite premultiplies.
  return vec4f(TINT, a);
}

// Fireworks — ported to WGSL from "Fireworks" by Gatomoi
// https://www.shadertoy.com/view/73sXWH
// The click-launched shells and the feedback trail are dropped: both needed
// extra buffers, and an effect here is a single pass.

// Tunables — edit and ⌘⏎.
//
// Sized UP for the half-res field pass: the sky holds nearly twice the shells,
// each bigger and hotter, and the arithmetic lands almost exactly on what the
// smaller show used to cost at full resolution. The culls are what let it
// scale — every pixel still rejects whole shells before touching a spark.
const SHELLS = 10;             // shells in the rotation
const PARTICLES = 72;          // sparks per shell — THE cost dial
const SECONDARY = 4;           // crackles each qualifying spark throws
const PERIOD = 5.0;            // seconds between a slot's launches
// 0.382 of the period — the golden-ratio conjugate, kept in step with PERIOD. A
// rounder fraction resonates: were this an eighth of the period, slots 0 and 8
// would launch in lockstep and the sky would clump instead of filling.
const STAGGER = 1.25;          // seconds between one slot and the next — at
                               // 3.35s of life that is ~2.7 shells in the air
                               // at once, against ~1.75 before
const CLIMB_SCALE = 1.6;       // stretches the climb only — a shell that shoots
                               // up instantly has no flight to watch
const SEQUENCE = 3.35;         // total life: climb + burst, and no longer — a slot
                               // past it is dead, so ending the window early is
                               // free frames
const BURST_TIME = 1.55;       // the reference's own burst length
// The reference's own value. Raising it was a mistake I made trying to force a
// visible fall — the fall is visible there because the trails DRAW it, not
// because the sparks drop harder, and a heavier one only made the burst hang
// below the point it went off at.
const GRAVITY = 0.32;
const CHILD_GRAVITY = 0.06;    // the same, for the embers
const CRACKLE_AT = 0.57;       // fraction of the burst before the secondaries go
const EXPOSURE = 1.8;
const SPEED = 0.85;            // clock multiplier — lower is slower, all of it
const BOOM = 1.15;             // how far the sparks throw — smaller sits further back
const WORLD_Z = 46.0;          // how far BEHIND the stage the shells rise
const WORLD_SPAN = 30.0;       // half-width of the firing line, world units
const WORLD_LOW = 17.0;        // burst heights, world units
const WORLD_HIGH = 30.0;
const REF_DIST = 55.0;         // the distance at which a shell wears its tuned size
const CLIMB_TRAIL = 0.045;     // how much of the climb the rocket's streak covers.
                               // Small, because the climb is EASED: at 0.2 the
                               // rocket has already flown half its path, so that
                               // much of "its past" is half the frame.
const HEAD_HALO = 0.022;       // how far the rocket's own glow carries
const CLIMB_GLOW = 2.6;        // brightness of that streak. Brightness IS opacity
                               // here: the layer's alpha is its own energy, so a
                               // dim streak is a see-through one.
const CLIMB_HALO = 0.006;       // and how WIDE it is allowed to be. Brightness and
                               // width are separate dials on purpose — a 1/r glow
                               // spreads as you brighten it, so without a bound
                               // the only legible streak is a fat one.

// The reference kept its streaks in a buffer that decayed 0.955/0.925/0.875 per
// frame, so a streak lived about this long — and PER CHANNEL, blue fastest. Both
// numbers below are that buffer, solved rather than eyeballed: at 60fps the decay
// rates are ln(1/0.955)·60 = 2.76 for red against 8.0 for blue, so a 0.37s-old
// piece of streak keeps 36% of its red and 5% of its blue. That is why the tails
// go orange, and it is a colour we can compute instead of guess at.
const TRAIL_SECONDS = 0.37;
const TRAIL_DECAY = vec3f(2.76, 4.68, 8.0);
const TRAIL_MIX = 0.72;        // what the reference composited that buffer at
const PLAIN_SHELLS = 0.1;      // fraction that burst with no trails at all
const SMALLEST = 0.7;          // the runt of the rotation, as a fraction of BOOM

const TAU = 6.28318530718;
// Every 1/r glow inside the cull is faded to exactly zero at this radius, and the
// cull is this radius past the farthest spark. That makes the boundary a
// definition rather than an estimate: nothing can be truncated, because nothing
// is still alive out there. Estimating it is what drew the ring — a glow reads as
// visible far further than its raw value suggests, since the tone map lifts it
// (alpha = 1 − exp(−1.52·c)) before the frame is quantised.
// Derived, not chosen: a spark's glow is size·0.78/d, so at the size above it
// falls under one code value at 0.32. Every glow inside the cull is faded to
// zero exactly here, which is what makes the boundary safe to cull on.
const GLOW_REACH = 0.52;
// One 8-bit code value, referred back through the tone map (alpha = 1 − exp(−1.52·c)).
// Anything dimmer than this cannot change a pixel, so it need not be drawn.
const VISIBLE = 0.0026;

fn background(ray: vec3f, uv0: vec2f, clock: f32) -> vec4f {
  // One dial for the whole display: shells, climbs, bursts and the sparkle rate
  // all read this clock, so slowing it slows them together instead of drifting
  // out of step with each other.
  let time = clock * SPEED;
  let res = bgResolution();
  // Square units, y in −1..1, x carrying the aspect — the convention this came
  // from, and the one the ballistics constants are tuned in.
  let uv = vec2f((uv0.x * 2.0 - 1.0) * (res.x / max(res.y, 1.0)), uv0.y * 2.0 - 1.0);

  var col = vec3f(0.0);
  for (var s = 0; s < SHELLS; s++) {
    let slot = f32(s);
    let offset = slot * STAGGER;
    if (time < offset) {
      continue;
    }
    // Each slot fires on its own cycle; floor() names the launch, and every
    // random the shell wears is drawn from that name, so it keeps its colour and
    // its scatter for as long as it burns.
    let cycle = floor((time - offset) / PERIOD);
    let elapsed = time - (cycle * PERIOD + offset);
    if (elapsed <= 0.0 || elapsed >= SEQUENCE) {
      continue;
    }
    let seed = vec2f(slot * 91.7 + cycle * 17.3, cycle * 41.9 + slot * 8.2);
    let wt = fwWorldTarget(slot, cycle);
    let pr = rzProject(wt);
    // Behind the lens, or close enough that the scale would explode: skip.
    if (pr.z < 4.0) { continue; }
    let pad = vec3f(wt.x + (fwHash(seed + vec2f(31.0, 4.0)) - 0.5) * 12.0, 0.0, wt.z);
    let pp = rzProject(pad);
    if (pp.z < 4.0) { continue; }
    let shellScale = clamp(REF_DIST / pr.z, 0.4, 1.6);
    col += fwSequence(uv, pr.xy * res, pp.xy * res, elapsed, seed, res, shellScale) * 0.82;
  }

  let vignette = smoothstep(0.84, 0.2, length(uv0 - 0.5));
  col *= 0.9 + 0.1 * vignette;

  // A soft shoulder rather than a clamp: highlights roll off instead of clipping
  // flat to white, which is what keeps a bright core its own colour.
  let mapped = 1.0 - exp(-max(col, vec3f(0.0)) * EXPOSURE);
  let energy = max(max(mapped.r, mapped.g), mapped.b);
  if (energy <= 0.0) {
    return vec4f(0.0);
  }
  // Hue in rgb, energy in alpha: the composite does rgb·a + background·(1−a),
  // so this reads as additive light while embers still let the sky through.
  return vec4f(mapped / energy, energy);
}

// Climb, then burst. One shell is only ever doing one of the two.
fn fwSequence(uv: vec2f, targetPixel: vec2f, startPixel: vec2f, elapsed: f32, seed: vec2f, res: vec2f, k: f32) -> vec3f {
  let climb = (0.9 + fwHash(seed + vec2f(45.0, 12.0)) * 0.18) * CLIMB_SCALE;
  if (elapsed < climb) {
    return fwRocket(uv, startPixel, targetPixel, elapsed / climb, seed, res, k);
  }
  let t = (elapsed - climb) / BURST_TIME;
  if (t < 1.0) {
    return fwBurst(uv, fwToWorld(targetPixel, res), t, seed, k);
  }
  return vec3f(0.0);
}

// ── The climb ──

fn fwRocket(uv: vec2f, startPixel: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f, k: f32) -> vec3f {
  let pos = fwRocketPos(startPixel, targetPixel, t, seed, res);
  // Where it was an instant ago: the streak is the segment between the two, which
  // is the only trail we get in a single pass — the original accumulated one in a
  // feedback buffer.
  let prev = fwRocketPos(startPixel, targetPixel, max(t - CLIMB_TRAIL, 0.0), seed, res);

  let tint = normalize(fwPalette(seed) + vec3f(1.0, 0.72, 0.35));
  // The head needs its own bound for the same reason the streak does: at this
  // amplitude a bare 1/r stays above one code value two whole screen-heights
  // out, so the rocket dragged a frame-sized smudge around with it. Bounded, it
  // is a point with a small halo.
  // Both endpoints are PROJECTED, so the streak's length and slope already
  // carry the perspective; only the widths need the shell's scale.
  let hd = length(uv - pos) / k;
  let head = (0.0022 / (hd + 0.0011) * smoothstep(HEAD_HALO, 0.0, hd) +
              exp(-hd * hd * 55000.0) * 1.7);

  // The streak gets a hard core as well as a glow, for the same reason the
  // sparks do: a glow alone is a smudge, and it is the core that reads as a
  // line. `age` is 0 at the far end, so the streak thins and dims backwards
  // instead of ending square.
  var arc = fwArc(uv, prev, pos);
  arc.x = arc.x / k;
  // Holds full strength for the first third of the climb rather than starting to
  // go immediately, so the streak is still legible when the shell is high.
  let fadeIn = smoothstep(1.3, 0.35, t);
  let taper = mix(0.55, 1.0, arc.y);
  // The halo is faded to nothing at CLIMB_HALO, so the streak has an actual
  // edge; the core carries the light. Roughly three pixels wide at 1080p, which
  // is a wire rather than a band.
  let glow = 0.0014 / (arc.x + 0.0016) * smoothstep(CLIMB_HALO, 0.0, arc.x) *
             fadeIn * taper * CLIMB_GLOW;
  // 260000 against the head's 55000: the streak's falloff is a bit over half the
  // head's width, so the rocket reads as a point DRAGGING a wire rather than a
  // wire with a bulge in it. They were within 10% of each other before.
  let core = exp(-arc.x * arc.x * 260000.0) * 2.2 * fadeIn * taper * CLIMB_GLOW;

  return tint * head + mix(tint, vec3f(1.0, 0.38, 0.12), 0.35) * (glow + core);
}

fn fwRocketPos(startPixel: vec2f, targetPixel: vec2f, t: f32, seed: vec2f, res: vec2f) -> vec2f {
  // Eased so it leaves fast and arrives slow, the way a shell running out of
  // thrust does. A FOURTH power, not a cube: it puts the rocket within a fraction
  // of a percent of its apex by four-fifths of the climb, so the last stretch is
  // a hang rather than an arrival. Without that pause the burst reads as going
  // off mid-flight — there is no moment of being at the top to go off AT.
  let x = clamp(t, 0.0, 1.0);
  let inv = 1.0 - x;
  let inv2 = inv * inv;
  var p = mix(fwToWorld(startPixel, res), fwToWorld(targetPixel, res), 1.0 - inv2 * inv2);
  // A little lateral bow, biggest mid-flight.
  p.x += sin(t * 3.14159265359) * (fwHash(seed + vec2f(17.0, 91.0)) - 0.5) * 0.055;
  return p;
}

// ── The burst ──

fn fwBurst(uvIn: vec2f, center: vec2f, t: f32, seed: vec2f, k: f32) -> vec3f {
  // The shell's whole private frame, scaled about its own centre: every tuned
  // distance below — velocities, reaches, glow radii — lands k times larger on
  // screen, which is all "nearer" means to a billboard burst.
  let uv = center + (uvIn - center) / k;
  // Nothing in this shell reaches farther than its fastest spark, plus the
  // crackles it throws, plus the distance a glow stays visible. Outside that
  // circle the loop below cannot contribute, so it is skipped whole — and a young
  // shell is nearly a point, which is when the saving is largest.
  let rel = uv - center;
  // Not every shell is the same shell: the small ones read as further away and
  // give the big ones something to be big against.
  let boom = BOOM * mix(SMALLEST, 1.0, fwHash(seed + vec2f(5.5, 2.2)));

  // The opening flash is a 1/r glow, so it reaches much further than the sparks
  // early on and nothing at all once it has decayed — its radius is derived
  // rather than guessed: the distance at which it falls under one code value.
  let flashAmp = exp(-t * 18.0) * 0.010;
  let flashReach = max(flashAmp / VISIBLE, 1e-4);

  // ONE test for the whole shell, against whichever of the two is currently
  // larger. Returning here costs a pixel nothing at all — not even the palette,
  // which is four hashes and two normalises that most pixels have no use for.
  let reach = max(flashReach,
                  (1.02 * t + 0.16 + 0.5 * GRAVITY * t * t + CHILD_GRAVITY) * boom + GLOW_REACH);
  if (dot(rel, rel) > reach * reach) {
    return vec3f(0.0);
  }

  let tint = fwPalette(seed);
  let flashDistance = length(rel);
  var col = normalize(tint + vec3f(1.0)) * flashAmp / (flashDistance + 0.0025) *
            smoothstep(flashReach, 0.0, flashDistance);

  let emberTint = normalize(tint + vec3f(0.9, 0.55, 0.25));
  let hotTint = normalize(tint + vec3f(1.0, 0.62, 0.22));
  // A tenth of shells burst with no streaks at all, which is what keeps the sky
  // from reading as one firework repeated.
  let trails = fwHash(seed + vec2f(101.7, 53.3)) >= PLAIN_SHELLS;
  // The streak's span in burst-time: one unit of t is BURST_TIME/SPEED seconds.
  let trailLen = select(0.0, TRAIL_SECONDS * SPEED / BURST_TIME, trails);
  let hSeed = fwHash(seed);

  let fade = smoothstep(0.82, 0.08, t);
  // The streaked layer outlives the sharp one and ramps in over the first frames
  // rather than arriving whole — both straight from the reference's second pass.
  let trailFade = smoothstep(0.95, 0.08, t) * smoothstep(0.0, 0.06, t);
  let crackleT = clamp((t - CRACKLE_AT) / (1.0 - CRACKLE_AT), 0.0, 1.0);

  // Radii for the rejects in the loop, hoisted — the same for every spark in the
  // shell. A spark's arc is no longer than its top speed plus gravity over the
  // streak's span; its embers stay within their own scatter.
  let sparkReach = (1.02 + GRAVITY) * boom * trailLen + GLOW_REACH;
  let emberReach = (0.16 + CHILD_GRAVITY) * boom + GLOW_REACH;

  for (var particle = 0; particle < PARTICLES; particle++) {
    let i = f32(particle);
    // An even fan, jittered, so the shell is round without being a stencil.
    let angle = i * (TAU / f32(PARTICLES)) + (fwHash(seed + vec2f(i, 13.1)) - 0.5) * 0.22;
    let velocity = vec2f(cos(angle), sin(angle)) * ((0.3 + 0.72 * fwHash(vec2f(i, hSeed))) * boom);

    let pos = fwBallistic(center, velocity, t, boom);

    // A pixel further from the spark than its whole arc plus a glow's reach
    // cannot be lit by any part of it. Skipping here skips the second ballistic,
    // the segment solve and all the shading — and a shell's sparks fan out over
    // ten times a glow's radius, so nearly all of them miss any given pixel.
    let toSpark = uv - pos;
    if (dot(toSpark, toSpark) <= sparkReach * sparkReach) {
      let sparkle = sin(t * 58.0 + i + hSeed * 12.0) * 0.5 + 0.5;

      // ── The sharp spark. Every one of them, drawn at where it IS. Gated on its
      // OWN radius, which is tighter than the reject above: that one has to cover
      // the streak's whole length, so between the two radii this maths would run
      // only to be multiplied by a window of zero.
      let d = length(toSpark);
      if (d < GLOW_REACH) {
        let size = 0.00125 * fade * (0.55 + 0.45 * sparkle);
        let glow = size / (d + 0.00062) * smoothstep(GLOW_REACH, 0.0, d);
        let core = exp(-d * d * 120000.0) * 1.35 * fade * (0.75 + 0.25 * sparkle);
        col += tint * (glow * 0.78 + core);
      }

      // ── The streak. EVERY OTHER spark, exactly as the reference's second pass
      // stepped its particle index by two: half the shell streaks and half stays
      // sharp, and it is the mixture that reads as fireworks rather than as a
      // net. Drawing it on all of them was what made the sky look woven.
      if (trails && (particle & 1) == 0) {
        let prev = fwBallistic(center, velocity, max(t - trailLen, 0.0), boom);
        // .x = distance to the arc, .y = where along it — 0 at the tail, 1 at
        // the spark. The second is the streak's own age, in seconds.
        let arc = fwArc(uv, prev, pos);
        let td = arc.x;
        if (td < GLOW_REACH) {
          // The decay the buffer applied over frames, applied over LENGTH
          // instead. Per channel, so the tail goes orange on its own rather than
          // being tinted orange by hand.
          let held = exp(-TRAIL_DECAY * ((1.0 - arc.y) * TRAIL_SECONDS));
          let tSize = 0.00105 * trailFade * (0.6 + 0.4 * sparkle);
          let tGlow = tSize / (td + 0.00072) * smoothstep(GLOW_REACH, 0.0, td);
          let tCore = exp(-td * td * 95000.0) * trailFade * (0.65 + 0.35 * sparkle);
          col += mix(tint, hotTint, 0.28 + sparkle * 0.2) * held *
                 (tGlow * 0.52 + tCore * 0.46) * TRAIL_MIX;
        }
      }
    }

    // Roughly two in five sparks crackle into a handful of embers. Tested
    // separately from the spark above, and NOT skipped with it: a crackle goes
    // off where the spark was at CRACKLE_AT, which by now is somewhere else
    // entirely.
    if (crackleT > 0.0 && fwHash(seed + vec2f(i, 71.7)) >= 0.58) {
      let origin = fwBallistic(center, velocity, CRACKLE_AT, boom);
      let toOrigin = uv - origin;
      if (dot(toOrigin, toOrigin) > emberReach * emberReach) {
        continue;
      }
      let flashDist = length(toOrigin);
      col += emberTint * exp(-crackleT * 20.0) * 0.0032 / (flashDist + 0.0018) *
             smoothstep(GLOW_REACH, 0.0, flashDist);

      for (var child = 0; child < SECONDARY; child++) {
        let j = f32(child);
        let cSeed = fwHash(seed + vec2f(i * 17.0, j * 23.0));
        let cAngle = TAU * (j / f32(SECONDARY) + cSeed * 0.35);
        let cVel = vec2f(cos(cAngle), sin(cAngle)) *
                   ((0.06 + 0.10 * fwHash(seed + vec2f(j * 9.0, i * 5.0))) * boom);

        var cPos = origin + cVel * crackleT;
        cPos.y -= CHILD_GRAVITY * boom * crackleT * crackleT;

        let cd = length(uv - cPos);
        let cFade = smoothstep(1.0, 0.05, crackleT);
        col += mix(emberTint, vec3f(1.0, 0.82, 0.42), cSeed * 0.45) *
               ((0.00088 * cFade) / (cd + 0.00062) * 0.75 * smoothstep(GLOW_REACH, 0.0, cd) +
                exp(-cd * cd * 150000.0) * 0.85 * cFade);
      }
    }
  }

  return col;
}

fn fwBallistic(center: vec2f, velocity: vec2f, t: f32, boom: f32) -> vec2f {
  // Gravity scales with the shell alongside the velocity it fights. Throwing the
  // sparks half again as far while they still drop the same 0.15 flattens every
  // arc into a straight fan — the trajectory has to grow with the shell, or the
  // shell stops falling.
  return center + velocity * t - vec2f(0.0, 0.5 * GRAVITY * boom * t * t);
}

// ── Toolbox ──

/**
 * Where shell (slot, cycle) bursts — a WORLD point behind the stage.
 *
 * The display used to be composed in screen space, which is why it moved with
 * the camera: it was wallpaper. Anchored in the world and projected each frame
 * (rzProject), the shells stay put while you orbit, sit behind the character
 * because the background mount composites behind the scene, and gain parallax
 * for free — a shell farther down the line is smaller because it IS farther.
 */
fn fwWorldTarget(slot: f32, cycle: f32) -> vec3f {
  let seed = vec2f(slot * 37.17 + cycle * 11.31, cycle * 23.73 + slot * 5.91);
  return vec3f(
    mix(-WORLD_SPAN, WORLD_SPAN, fwHash(seed + vec2f(1.0, 0.0))),
    mix(WORLD_LOW, WORLD_HIGH, fwHash(seed + vec2f(0.0, 1.0))),
    WORLD_Z + (fwHash(seed + vec2f(2.0, 7.0)) - 0.5) * 14.0,
  );
}

/** Pixels → the square, y-normalised space everything above is tuned in. */
fn fwToWorld(pixel: vec2f, res: vec2f) -> vec2f {
  return (pixel * 2.0 - res) / max(res.y, 1.0);
}

fn fwPalette(seed: vec2f) -> vec3f {
  // A pyrotechnician's palette, not noise. Random RGB pulled toward warm or
  // cool and normalised always averaged out to pastel — every shell the same
  // washed grey-gold. Real shows read as NAMED colours: strontium red, sodium
  // gold, barium green, copper blue... eight of them, picked per shell, with a
  // small wobble so two reds are sisters rather than twins.
  let pick = i32(fwHash(seed + vec2f(11.3, 0.7)) * 7.99);
  var c = vec3f(1.0, 0.92, 0.80);                  // 7: white-gold
  if (pick == 0) { c = vec3f(1.0, 0.22, 0.20); }   // strontium red
  if (pick == 1) { c = vec3f(1.0, 0.62, 0.16); }   // sodium gold
  if (pick == 2) { c = vec3f(1.0, 0.92, 0.35); }   // champagne
  if (pick == 3) { c = vec3f(0.30, 1.0, 0.42); }   // barium green
  if (pick == 4) { c = vec3f(0.25, 0.85, 1.0); }   // cyan
  if (pick == 5) { c = vec3f(0.35, 0.45, 1.0); }   // copper blue
  if (pick == 6) { c = vec3f(1.0, 0.35, 0.75); }   // magenta
  let wob = (fwHash(seed + vec2f(2.1, 19.8)) - 0.5) * 0.18;
  return normalize(c + vec3f(wob, -wob * 0.5, wob * 0.3));
}

/** Distance to the segment ab — the rocket's streak. */
fn fwSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  return fwArc(p, a, b).x;
}

/** Distance to segment ab, and how far along it the nearest point sits (0 at a,
 *  1 at b). A spark's streak needs both: the distance draws it, the position
 *  along it ages it. */
fn fwArc(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 0.00001), 0.0, 1.0);
  return vec2f(length(pa - ba * h), h);
}

fn fwHash(p0: vec2f) -> f32 {
  var p = fract(p0 * vec2f(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

// @anchor 左手首 trail
// @anchor 右手首 trail
// @particles 320
// @blend additive
// @bloom

// A neon ribbon along the path each hand actually took — with the sparks it
// sheds living as real GPU particles.
//
// The fullscreen original walked up to 128 trail samples PER PIXEL and drew its
// sparks by looping over every path sample at every pixel; it looked right and
// cost the frame rate. This version draws the same recorded history as
// geometry: 127 spline-smoothed segments per hand, and the sparks are the first
// use of both mounts in one file — particleInit spawns them ON the trail, from
// the same buffer the ribbon reads.
//
// The ribbon renders into its OWN layer, max-blended — the original's
// core-takes-the-max rule as a blend mode — then composites over the frame
// AFTER tone mapping, exactly where the fullscreen version ran. Max is why the
// parallel strands of a circling hand cannot double into bright dashes, and
// post-tonemap is why these colours reach the screen verbatim, never bleached
// by AgX. (The @blend/@bloom pragmas below apply to the SPARKS, which are
// particles in the scene pass; the ribbon's blending is fixed by the layer.)
//
// Tunables — edit and ⌘⏎.
const CORE_COLOR = vec3f(0.86, 0.97, 1.0);   // white-hot, faintly blue
const BODY_COLOR = vec3f(0.12, 0.42, 1.0);   // electric blue
const HAZE_COLOR = vec3f(0.34, 0.10, 0.98);  // violet, in the outer light

const LIFETIME = 0.60;   // seconds of path drawn behind the hand — tight arc, no stale tail
// PIXELS, exactly as the original measured — the ribbon is extruded in screen
// space now, so the constant means what it meant there, and the trail holds its
// width on screen at any camera distance.
const WIDTH = 42.0;      // half-width of the GLOW in pixels at 1080p
const CORE_FRAC = 0.21;  // the hot core inside it — the original's 7px in 34
const TAIL_WIDTH = 0.40; // core width at the far end, as a fraction
const TAIL_EASE = 0.22;  // last stretch of life spent fading to nothing
// Rebalanced toward the saber grammar: the white-hot part is a THIN line and
// the saturated colour is most of the visible width. CORE high makes white
// spread; HALO carries the neon.
const CORE = 2.6;        // weight of the core — what makes it read as light
// 0.55 in the original — times the overlap its `+=` accumulated. There every
// pixel SUMMED every segment within the glow radius (about 1.5 segments' worth
// on a straight path); here the quads tile, so each pixel samples the profile
// once and the weight carries the difference.
const HALO = 0.85;
const LIGHT = 1.35;      // final gain on the ribbon's alpha

// Sparks. World units; a model stands ~20 units tall, judge against that.
// Sparks are PARTICLES, so unlike the ribbon they render in the scene pass and
// pass through AgX — which bleaches any bright tint toward white. The colour
// has to be DEEP, with the lightness confined to the pinpoint centre.
const SPARK_COLOR = vec3f(0.36, 0.24, 1.0);  // deep neon violet-blue, the halo
const SPARK_HOT = vec3f(0.72, 0.60, 1.0);    // the pinpoint, kept lavender
const SPARK_LIFE = 0.70;  // seconds — at or below LIFETIME, or dots outlive the trail
const SPARK_EMERGE = 0.30;// spent fading in, while it swings clear of the ribbon
const SPARK_SIZE = 0.07;
const ORBIT_SPEED = 2.5;  // how hard the path curls sideways as it flies
const DRIFT = 2.6;        // outward speed at birth — clear the ribbon fast
const RISE = 2.4;         // upward drift
const TWINKLE = 9.0;
const SPARK_INTENSITY = 1.7;   // low, or AgX's shoulder eats the hue

// ── The ribbon ──────────────────────────────────────────────────────────────

fn trailWidth(u: f32, age: f32) -> f32 {
  // The quad IS the glow, and the glow keeps a constant radius — only the core
  // narrows down the tail (in trailShade). The width itself just closes the very
  // end so the oldest sample is not a hard edge, and it deliberately ignores how
  // fast the hand moves: pinching where the hand slows breaks the ribbon at
  // every turn, because a turn is where a hand decelerates.
  let a = clamp(1.0 - age / LIFETIME, 0.0, 1.0);
  // rzViewportHeight()/1080 is the original's pxK: the same effect at a 4K
  // export and in the editor, instead of a different-looking one per resolution.
  return WIDTH * (rzViewportHeight() / 1080.0) * smoothstep(0.0, TAIL_EASE, a);
}

fn trailShade(u: f32, v: f32, age: f32, weight: f32, slot: i32) -> vec4f {
  // `a` runs 1 at the hand to 0 at the end of LIFETIME, exactly as the original.
  let a = clamp(1.0 - age / LIFETIME, 0.0, 1.0);
  let ease = smoothstep(0.0, TAIL_EASE, a);
  let bright = a * a * ease;
  let d = abs(v);

  // A GAUSSIAN core inside a compact-support halo — the original's two shapes.
  // `weight` is the engine's segment length over a full contribution: the line
  // integral, so a pausing hand goes dim and blue instead of white.
  let frac = CORE_FRAC * mix(TAIL_WIDTH, 1.0, pow(a, 0.7));
  let core = exp(-(d * d) / max(frac * frac, 1e-6)) * bright * weight;
  let halo = rzFalloff(d, 1.0) * bright * weight;
  let heat = core * CORE + halo * HALO;

  // Colour FROM intensity: white only where it is genuinely hot, azure through
  // the body, deep blue in the outer light.
  var rgb = mix(HAZE_COLOR, BODY_COLOR, smoothstep(0.03, 0.40, heat));
  rgb = mix(rgb, CORE_COLOR, smoothstep(0.45, 1.30, heat));
  // No gain, no tone-map compensation: the layer composites after AgX, so what
  // is written here is what appears — the original's own contract.
  return vec4f(rgb, clamp(heat * LIGHT, 0.0, 1.0));
}

// ── The sparks ──────────────────────────────────────────────────────────────

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let h = rzHash13(seed + f32(id) * 0.0193);
  let h2 = rzHash13(seed * 3.1 + f32(id) * 0.0711);
  // A hand, a character, a recent point on that hand's path.
  let slot = i32(h.x * f32(RZ_TRAIL_SLOTS));
  var subject = i32(h.y * 4.0) % 4;
  if (rzTrailCount(subject, slot) < 6) { subject = 0; }
  let n = rzTrailCount(subject, slot);
  // Half a second of real history before the FIRST spark — a catch-all for
  // every first-frame path shape (bind pose, load pop-in, first-pose snap):
  // whatever those look like, a freshly started trail sits out the grace and a
  // burst at scene start is impossible by construction, not by enumeration.
  if (n < 6 || rzTrail(subject, slot, n - 1).w < 0.5) {
    p.life = 0.0;
    return p;
  }
  // Spread along the recent path, not piled at the live end — 512 sparks all
  // born at the newest five samples was a permanent starburst welded to the
  // hand, and its bloom spikes read as burrs on the ribbon.
  let k = 1 + i32(h.z * 24.0);
  let sampleA = rzTrail(subject, slot, k);
  let sampleB = rzTrail(subject, slot, min(k + 2, n - 1));
  // Sparks are shed by MOTION, so a still path sheds none. A resting hand keeps
  // a trail — a cluster of near-identical samples — and unguarded spawns
  // fountained from it while the ribbon itself rightly drew nothing. The same
  // guard kills the burst at the world origin while a model loads: its bones
  // sit at (0,0,0) then, which is just another perfectly still path.
  if (distance(sampleA.xyz, sampleB.xyz) < 0.06) {
    p.life = 0.0;
    return p;
  }
  p.pos = sampleA.xyz;
  // Thrown outward and upward; the swirl in the step curls the path.
  let phase = h2.x * 6.2831853;
  p.vel = vec3f(cos(phase) * DRIFT, RISE * 0.5, sin(phase) * DRIFT);
  p.size = SPARK_SIZE * (0.6 + 0.9 * h2.y);
  p.life = SPARK_LIFE * (0.7 + 0.5 * h2.z);
  p.seed = h2.x * 39.0 + h.z * 17.0;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Curl the horizontal velocity, so a spark orbits away from the path rather
  // than flying a straight line off it.
  let c = cos(ORBIT_SPEED * dt);
  let s = sin(ORBIT_SPEED * dt);
  q.vel = vec3f(q.vel.x * c - q.vel.z * s, q.vel.y + RISE * 0.6 * dt, q.vel.x * s + q.vel.z * c);
  q.pos = q.pos + q.vel * dt;
  return q;
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let dd = length(q);
  let t = clamp(p.age / max(p.life, 1e-3), 0.0, 1.0);
  // Fade IN first: a spark born at full brightness is a bright dot sitting on
  // the ribbon. By the time it is visible it has swung clear.
  let emerge = smoothstep(0.0, SPARK_EMERGE / SPARK_LIFE, t);
  let fall = (1.0 - t) * (1.0 - t);
  let twinkle = 0.4 + 0.6 * sin(rzTime() * TWINKLE + p.seed);
  // A hard pinpoint inside a soft bloom — a spark, not a smudge.
  let soft = exp(-(dd * dd) / 0.5);
  let hot = exp(-(dd * dd) / 0.08);
  let alpha = clamp((soft * 0.55 + hot) * fall * twinkle * emerge, 0.0, 1.0);
  // Two-tone: violet halo, lavender heart — colour from intensity, the ribbon's
  // own rule at spark scale.
  let rgb = mix(SPARK_COLOR, SPARK_HOT, clamp(hot, 0.0, 1.0));
  return vec4f(rgb * SPARK_INTENSITY, alpha);
}

// @anchor 左足ＩＫ trail
// @anchor 右足ＩＫ trail
// @anchor 左足首 trail
// @anchor 右足首 trail

// Tunables — edit and ⌘⏎.
// Colour comes from INTENSITY, not from a single tint. A disc filled with one
// saturated colour and then alpha-blended over a dark floor lands somewhere in
// the middle and reads muddy — which is how a red print came out dark orange.
// Light goes WHITE where it is strong and keeps its colour only as it falls off.
const HOT_COLOR = vec3f(0.88, 0.99, 1.0);    // white-cyan, centre of a fresh print
const GLOW_COLOR = vec3f(0.14, 0.76, 1.0);   // cyan, the body of it
const RIM_COLOR = vec3f(0.05, 0.30, 0.95);   // deep blue, at the edge
const RADIUS = 2.4;      // world units — a mark a foot sits INSIDE, not one it
                         // covers, or the print reads as a dot under the shoe
const EDGE = 0.5;        // soft rim as a fraction of the radius
// How much the foot must have dropped for a sample to read as a landing. A
// RELATIVE test, never an absolute height: 足ＩＫ sits at the ANKLE, already a
// hand's width up on a bare foot and higher in heels, so any constant measured
// from the floor is wrong on some rig.
const TOUCH_EPS = 0.03;
const FADE = 2.0;        // seconds a print takes to burn out
// What rises off a print as it burns out. Motes, not a column: a column is one
// solid shape and it reads as a shape — two rims, a lit tube between them. A
// print going out like a candle is a disc that dims while sparks leave it, and
// sparks are what carry that. They are placed in SCREEN space around the
// projected print, so seven of them cost two projections rather than seven.
const EMBERS = 128;       // motes rising off each print
const EMBER_LIFE = 1.60;  // seconds one lives
const EMBER_RISE = 4.2;   // world units per second it climbs
const EMBER_VARY = 0.70;  // how much that speed differs mote to mote
const EMBER_SPREAD = 0.10;// how much further OUT it drifts as it climbs. Small
                          // on purpose: anything generous here and the sparks
                          // leave from outside the mark they belong to
const EMBER_R = 0.11;     // its radius, the same
const EMBER_CORE = 0.72;  // fraction of that which is SOLID before it falls off
const EMBER_SIZES = 0.6;  // how much THAT differs mote to mote
const EMBER_I = 1.7;      // how bright, against the mark on the floor
const FLATNESS = 0.22;   // world units of ground the mark may lie on
// EVERY sample. The ring shifts by one each frame, so a given moment of the
// path sits on an even index one frame and an odd one the next — striding over
// it means a landing is detected every OTHER frame, and the print strobes at
// half the framerate. The body below is two reads and two compares until a
// landing is actually found, so visiting every index is cheap.
const STRIDE = 1;
const ELONGATE = 1.0;    // 1 = round; above 1 stretches along the step
const STRENGTH = 2.3;
const FAR_CLAMP = 400.0;

// Marks where the feet met the ground, left behind as the character walks away.
//
// The worked example for rzSubject().root and for reading a trail in WORLD space
// rather than on screen. It was called Footfalls and only lit the foot's current
// position, which followed the foot around like a spotlight — a foot's location,
// not a footprint.
//
// A print is a place and a TIME: born where the foot met the floor, then burning
// down while the foot walks on. rzTrail carries exactly that — every sample is a
// position plus how many seconds ago it was there — so the samples whose height
// is near the floor ARE the contacts, and their age is how long ago each one
// happened. That is a real print that stays behind, out of data the engine keeps
// for a hand ribbon.
//
// It is still an approximation of contact rather than the thing itself: engine
// contact events would give the exact frame a foot landed, its facing and how
// hard, where this infers it from height. Good enough to look right, and the
// comment is here so the next person knows which part is the stand-in.
//
// The height test is also why the band has to be tight: a shoe's toe is a few
// centimetres off the ground, so a generous band marks the toe as readily as the
// floor under it. Position alone cannot tell them apart — they are in the same
// place. Knowing which pixels are the CHARACTER would, and that needs the subject
// mask the engine does not expose yet.
/** Returns the mark on the FLOOR in x, and the light standing on it in y. */
fn fpHash(p: vec2f) -> vec2f {
  let q = vec2f(dot(p, vec2f(127.1, 311.7)), dot(p, vec2f(269.5, 183.3)));
  return fract(sin(q) * 43758.5453);
}

/** Returns the mark on the FLOOR in x, and what rises off it in y. */
fn markFor(subject: i32, slot: i32, alt: i32, p: vec3f, sp: vec2f, aspect: f32,
           ro: vec3f, ray: vec3f, depth: f32) -> vec2f {
  var n = rzTrailCount(subject, slot);
  var pick = slot;
  if (n < 2) {
    n = rzTrailCount(subject, alt);
    pick = alt;
  }
  if (n < 4) { return vec2f(0.0); }

  // Cull in world space: the whole walk fits in a circle, and most of the floor
  // is nowhere near it.
  var mid = vec2f(0.0);
  for (var k = 0; k < 4; k++) {
    mid += rzTrail(subject, pick, min(k * n / 3, n - 1)).xz;
  }
  mid *= 0.25;
  var reach = 0.0;
  for (var k = 0; k < 4; k++) {
    reach = max(reach, distance(rzTrail(subject, pick, min(k * n / 3, n - 1)).xz, mid));
  }
  // Cull on the RAY, not on the surface point.
  //
  // The floor test alone was right while this only drew on the floor: the pixel
  // was the mark. A pillar stands in the air, so a ray that passes straight
  // through one on its way to a wall fifty metres behind has a surface point
  // nowhere near the walk, and culling on it would erase the very pixels the
  // pillar lives in. Closest approach to a vertical axis through the middle of
  // the walk covers both — it is exactly the surface test when the ray ends on
  // the floor there, and looser everywhere the pillar needs it to be.
  let denom = max(1.0 - ray.y * ray.y, 1e-4);
  let w0 = ro - vec3f(mid.x, 0.0, mid.y);
  let near = ro + ray * max((ray.y * w0.y - dot(ray, w0)) / denom, 0.0);
  if (distance(near.xz, mid) > reach * 1.5 + RADIUS) { return vec2f(0.0); }

  var acc = 0.0;
  var col = 0.0;
  for (var i = STRIDE; i + STRIDE < n; i = i + STRIDE) {
    let s = rzTrail(subject, pick, i);
    if (s.w > FADE) { break; }               // older than a print lasts

    // TOUCHDOWN, not "low". Index 0 is now and rising indices run backwards in
    // time, so `older` is where the foot was before this sample and `newer` is
    // where it went after. A landing is the moment it STOPS descending: it was
    // higher a moment ago, and it did not keep dropping.
    //
    // Marking every low sample instead — which is what this did — puts a print
    // every 20ms through the whole stance, forty overlapping discs that merge
    // into one blob and flicker as each new one is born a few centimetres from
    // the last. A step should leave ONE print, and the path already says
    // exactly when it happened.
    let older = rzTrail(subject, pick, i + STRIDE).y;
    let newer = rzTrail(subject, pick, i - STRIDE).y;
    if (older - s.y < TOUCH_EPS) { continue; }   // was not descending
    if (s.y - newer > TOUCH_EPS) { continue; }   // still descending

    // Elongate along the direction of travel: a footprint is longer than it is
    // wide, and the step direction is the only orientation trail data carries.
    // (The foot's actual facing would need per-contact data — see the note above.)
    let travel = s.xz - rzTrail(subject, pick, i + STRIDE).xz;
    var axis = vec2f(0.0, 1.0);
    if (length(travel) > 1e-4) { axis = normalize(travel); }
    let perp = vec2f(-axis.y, axis.x);
    let age = 1.0 - clamp(s.w / FADE, 0.0, 1.0);
    let fade = age * age;

    // The mark on the floor, BURNING DOWN: it dims and it also draws in, the
    // way a candle's pool of light does. Fading alone leaves a disc of the same
    // size going grey, which reads as a light being turned down rather than as
    // something being used up.
    let burn = RADIUS * (0.60 + 0.40 * age);
    let rel = p.xz - s.xz;
    let local = vec2f(dot(rel, axis) / ELONGATE, dot(rel, perp));
    let dist = length(local);
    if (dist <= burn) {
      // Compact support: zero at the rim, so the cull leaves no hard edge.
      acc = max(acc, (1.0 - smoothstep(burn * (1.0 - EDGE), burn, dist)) * fade);
    }

    // The light standing on it, INTEGRATED through the slab of air it occupies.
    //
    // Closest approach to the axis is the right primitive for a filled
    // cylinder, where the nearest point is also the brightest and carries the
    // whole shape. It is the wrong one for a WALL: a ray that goes straight
    // through a pillar crosses the wall twice and should come out bright, yet
    // its closest approach lands in the hollow middle and reports nothing at
    // all. Only rays that happened to graze a wall tangentially survived, which
    // is why the light arrived as a few thin streaks sitting nowhere near the
    // prints they belonged to.
    //
    // Six samples between where the ray enters the pillar's height band and
    // where it leaves — or where the scene stops it, so a leg in front cuts the
    // light rather than glowing through it.
    // The embers. Placed in SCREEN space off the projected print: one
    // projection puts the print on the frame, a second puts a world-up metre on
    // it, and from those two every mote's rise, drift and size follow without a
    // projection of its own. Rising along a projected world up rather than the
    // frame's own +y is what keeps them going up when the camera is tilted.
    // From the FLOOR, not from the sample. A trail sample is a bone, and 足ＩＫ
    // sits at the ankle — already a hand's width up on a bare foot and higher in
    // heels — so sparks launched from it start in mid-air above the mark they
    // are supposed to be leaving. The subject's root is where the ground is.
    let gy = rzSubject(subject).root.y;
    let g0 = vec3f(s.x, gy, s.z);
    let pc = rzProject(g0);
    if (pc.z > 0.0) {
      // The GROUND PLANE, as two screen vectors. Screen up alone can only place
      // a mote along a line, and the disc is a disc: to leave from anywhere on
      // it, a mote needs the print's own two ground axes projected as well.
      // Four projections per print, and every one of the hundred-odd motes
      // below is then plain arithmetic.
      let pu = rzProject(g0 + vec3f(0.0, 1.0, 0.0));
      let pa = rzProject(g0 + vec3f(axis.x, 0.0, axis.y));
      let pp = rzProject(g0 + vec3f(-axis.y, 0.0, axis.x));
      let base = vec2f(pc.x * aspect, pc.y);
      let upv = vec2f(pu.x * aspect, pu.y) - base;
      let ax2 = vec2f(pa.x * aspect, pa.y) - base;
      let pz2 = vec2f(pp.x * aspect, pp.y) - base;

      // One circle around the whole plume, before any of it is worked out.
      // At this count the motes are the entire cost of the effect, and all of
      // them are inside a patch of frame a hand's breadth across — so the
      // pixels that are not in that patch must never touch the loop at all.
      let climbMax = EMBER_RISE * (1.0 + EMBER_VARY * 0.5) * EMBER_LIFE;
      let wide = burn * (1.0 + EMBER_SPREAD) * max(length(ax2), length(pz2))
               + EMBER_R * (1.0 + EMBER_SIZES) * length(upv);
      let plumeC = base + upv * (climbMax * 0.5);
      let plumeR = length(upv) * climbMax * 0.5 + wide;
      // Hidden where the scene is NEARER than the print — a leg in front cuts
      // the sparks rather than letting them glow through it.
      let occ = 1.0 - smoothstep(pc.z - 0.4, pc.z + 0.4, depth);
      if (occ < 0.999 && dot(sp - plumeC, sp - plumeC) <= plumeR * plumeR) {
        for (var k = 0; k < EMBERS; k++) {
          let key = floor(s.x * 13.0 + s.z * 7.0);
          let h = fpHash(vec2f(f32(k) + 1.0, key));
          let g = fpHash(vec2f(key + 3.7, f32(k) * 2.3 + 5.1));
          // Staggered births across the print's life, so they leave in a
          // stream rather than all at once.
          let el = s.w - (f32(k) + h.x) / f32(EMBERS) * FADE;
          if (el < 0.0 || el > EMBER_LIFE) { continue; }
          let t = el / EMBER_LIFE;
          // WHERE ON THE DISC it left from — uniform over the area, which is
          // what the square root does. Without it they crowd the centre, and
          // the print looks like it is venting through a hole.
          let ang = h.y * 6.2831853;
          // Against the disc's LIT radius, not its geometric one. The mark
          // fades out across EDGE of itself, so the circle anyone can actually
          // see ends well inside `burn` — spawning against `burn` put the whole
          // spray out in the invisible skirt, reading as sparks leaving from a
          // ring around the print rather than from the print. Derived from EDGE
          // so it follows if the rim is ever made softer or harder.
          let lit = burn * (1.0 - EDGE * 0.65);
          let rad = sqrt(g.y) * lit * (1.0 + EMBER_SPREAD * t);
          let out = ax2 * cos(ang) + pz2 * sin(ang);
          // Its own climb rate and its own size. Without these a crowd this
          // large rises as a rank of identical dots — the variation is what
          // turns a hundred motes into a spray rather than a row.
          let climb = EMBER_RISE * (1.0 - EMBER_VARY * 0.5 + EMBER_VARY * g.x);
          let q = base + out * rad + upv * (climb * el);
          let r = EMBER_R * (1.0 - EMBER_SIZES * 0.5 + EMBER_SIZES * fract(g.x * 7.3))
                * (1.0 - t * 0.55) * max(length(upv), 1e-5);
          // Solid to EMBER_CORE, then falling off. Ramping from the very
          // centre puts half the brightness in the outer skirt, so a mote this
          // small only ever reaches full at a single point and the field pass
          // runs at half resolution — between them, the dot upsamples into
          // nothing. A flat core survives that; a peak does not.
          let mote = 1.0 - smoothstep(r * EMBER_CORE, r, length(sp - q));
          col = max(col, mote * (1.0 - t) * (1.0 - t) * fade * EMBER_I * (1.0 - occ));
        }
      }
    }
  }
  return vec2f(acc, col);
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let ro = rzCameraPos();
  // Where the scene put a surface. Meaningless past the far clamp, and the
  // floor test below rejects it there — but the pass no longer returns early on
  // it, because a pillar over open sky is drawn on a pixel that has no surface
  // at all.
  let p = rzWorldPos(ray, min(depth, FAR_CLAMP));
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // The pixel itself, in a square space — where the embers are measured.
  let sp = vec2f(uv.x * aspect, uv.y);

  var acc = 0.0;
  for (var i = 0; i < rzSubjectCount(); i++) {
    let s = rzSubject(i);
    if (!s.valid) { continue; }
    // On the FLOOR, and only on the floor: xz alone describes a vertical
    // cylinder, which paints up the legs and everything else standing in it.
    // This gates the MARK only — the pillar is meant to be off the floor.
    let flat = select(0.0, 1.0 - smoothstep(FLATNESS * 0.5, FLATNESS, abs(p.y - s.root.y)), depth < FAR_CLAMP);
    let a = markFor(i, 0, 2, p, sp, aspect, ro, ray, depth);
    let b = markFor(i, 1, 3, p, sp, aspect, ro, ray, depth);
    acc = max(acc, max(a.x, b.x) * flat);
    acc = max(acc, max(a.y, b.y));
  }
  let heat = acc * STRENGTH;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Deep blue at the rim, cyan through the body, white-hot in the middle of a
  // fresh print — and the whole thing cools as it ages, because `acc` carries
  // the age fade into the intensity this reads.
  var rgb = mix(RIM_COLOR, GLOW_COLOR, smoothstep(0.04, 0.45, heat));
  rgb = mix(rgb, HOT_COLOR, smoothstep(0.55, 1.25, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

// @anchor センター trail

// Tunables — edit and ⌘⏎.
const COLOR_L = vec3f(0.60, 0.76, 1.0);   // stage left, cool
const COLOR_T = vec3f(1.0, 0.98, 0.95);   // overhead, white
const COLOR_R = vec3f(1.0, 0.74, 0.86);   // stage right, warm
const HEIGHT = 42.0;     // world units above the floor the lamps hang
const SPREAD = 25.0;     // how far left and right of centre they sit — this
                         // against HEIGHT is the rake angle of the outer beams
const FRONT = 7.0;       // ...and how far toward the audience
const TOP_R = 2.4;       // beam radius at the lamp
const BOT_R = 4.8;       // ...and where it lands — close to TOP_R keeps the
                         // shaft near parallel instead of a wide fan
const EDGE = 0.09;       // softness of the shaft's rim, as a fraction of BOT_R
const DENSITY = 0.7;     // how much haze the beam lights up
const POOL_R = 3.6;      // bright pool on the floor — inside the beam's landing
const POOL = 0.16;
const FLATNESS = 0.35;   // world units of ground the pool may lie on
const LAG = 0.30;        // seconds the aim trails the dancer
const AIM_STRIDE = 4;    // trail samples skipped when averaging the aim
const STEPS = 20;        // march steps. Twenty against the beam's own cylinder
                         // samples DENSER than thirty-four did against the old
                         // bounding sphere, which was mostly empty air
const FAR_CLAMP = 400.0;

// Follow-spots that track the cast.
//
// The worked example for rzSubject().root: the beams aim at the FLOOR under each
// character, so they follow a dancer across the stage the way an operator would,
// and land where the feet are rather than around the waist.
//
// The lamps are placed relative to the CAMERA — left, overhead, right, all in
// front of the character — so they read as stage lighting from wherever you
// orbit. Pinned to world axes they end up behind the subject half the time,
// which is backlight, not a follow-spot.
//
// The beam is volumetric, marched through the air, which is why it is occluded
// correctly: the march ends at the scene's own depth, so a shaft passes in front
// of a character and stops behind her.
fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

/**
 * Where lamp i hangs: side is -1, 0, +1 for left, overhead, right.
 *
 * WORLD-FIXED, fully: rigged to the stage's own axes, no camera term and no
 * sway. Earlier versions placed the rig around the camera's side of the stage
 * so it always read left/overhead/right — but that swings the lamp heads on
 * every orbit and every camera cut, and a fixture that moves is no fixture.
 * Only the AIM follows anything now; orbit behind the stage and you are simply
 * seeing the rig from behind, which is what a rig does.
 */
fn lampPos(side: f32, floorY: f32) -> vec3f {
  return vec3f(side * SPREAD, floorY + HEIGHT, FRONT);
}

/**
 * Where the beams point: the dancer, but lagged.
 *
 * An operator does not snap a follow-spot onto a moving target and neither
 * should this — an aim locked exactly to the hips twitches on every step and
 * makes the beam feel weightless. This is the same damping the follow camera
 * uses, done differently because a shader keeps nothing between frames: an
 * exponentially weighted average over the センター trail IS a low-pass filter,
 * and the trail is a position history we already have.
 *
 * LAG is the time constant. Larger drifts more lazily behind her; zero would be
 * the twitchy lock this exists to avoid.
 */
fn aimPoint(subject: i32, root: vec3f) -> vec3f {
  let n = rzTrailCount(subject, 0);
  if (n < 2) { return root; }
  var sum = vec3f(0.0);
  var wsum = 0.0;
  for (var i = 0; i < n; i = i + AIM_STRIDE) {
    let s = rzTrail(subject, 0, i);
    // Past two time constants the weight is already under a seventh — the rest
    // of the trail cannot move the average enough to be worth walking.
    if (s.w > LAG * 2.0) { break; }
    let we = exp(-s.w / LAG);
    sum += s.xyz * we;
    wsum += we;
  }
  if (wsum < 1e-4) { return root; }
  let p = sum / wsum;
  // Horizontal only: the aim follows where she IS on the stage, and the beam
  // still lands on the floor rather than chasing her hips up and down.
  return vec3f(p.x, root.y, p.z);
}

fn beamFor(side: f32, aim: vec3f, origin: vec3f, ray: vec3f, tMax: f32, time: f32, jitter: f32) -> f32 {
  let apex = lampPos(side, aim.y);
  let toFloor = aim - apex;
  let len = length(toFloor);
  if (len < 1e-3) { return 0.0; }
  let dir = toFloor / len;

  // March the BEAM's true envelope: its cylinder, cut by the lamp and floor
  // planes. Stepping uniformly from the lens to the scene gives every pixel a
  // different interval; and the earlier fix — a bounding SPHERE around the whole
  // beam — was still five times fatter than the beam it contained (radius
  // len/2 + BOT_R against a shaft at most BOT_R wide), so most of a fixed step
  // budget landed in empty air and failed the d < r test below. Against the
  // tight envelope, twenty steps hold the sampling density thirty-four needed
  // inside the sphere, and the jitter hides the rest.
  let w0 = origin - apex;
  let rd = dot(ray, dir);
  let wd = dot(w0, dir);
  var t0 = 0.0;
  var t1 = tMax;
  if (abs(rd) > 1e-4) {
    let ta = (0.0 - wd) / rd;
    let tb = (len - wd) / rd;
    t0 = max(t0, min(ta, tb));
    t1 = min(t1, max(ta, tb));
  } else if (wd < 0.0 || wd > len) {
    return 0.0;
  }
  let aq = 1.0 - rd * rd;
  let bq = dot(w0, ray) - wd * rd;
  let cq = dot(w0, w0) - wd * wd - BOT_R * BOT_R;
  if (aq > 1e-5) {
    let disc = bq * bq - aq * cq;
    if (disc < 0.0) { return 0.0; }
    let sq = sqrt(disc);
    t0 = max(t0, (-bq - sq) / aq);
    t1 = min(t1, (-bq + sq) / aq);
  } else if (cq > 0.0) {
    return 0.0;
  }
  if (t1 <= t0) { return 0.0; }

  var acc = 0.0;
  let dt = (t1 - t0) / f32(STEPS);
  for (var s = 0; s < STEPS; s++) {
    // JITTERED start. Every pixel sampling at the same offsets makes each step
    // deposit a visible disc, and a marched cone comes out as a stack of
    // spheres — worse the harder the beam's edge is, which is exactly when you
    // want it. Offsetting each pixel by a hash turns that banding into fine
    // noise, which is what haze looks like anyway.
    let p = origin + ray * (t0 + dt * (f32(s) + jitter));
    let along = clamp(dot(p - apex, dir) / len, 0.0, 1.0);
    let r = mix(TOP_R, BOT_R, along);
    let d = distance(p, apex + dir * (along * len));
    if (d < r) {
      // A searchlight has a defined SHAFT: flat across its width, falling off
      // only at the rim. The rim is a WORLD width, not a fraction of the local
      // radius — as a fraction it widens with the cone, leaving the beam sharp
      // at the lamp and smeared where it lands, which is the end you look at.
      let soft = max(EDGE * BOT_R, 1e-3);
      acc += smoothstep(r, r - soft, d) * mix(0.55, 1.0, along) * dt;
    }
  }
  return acc;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let origin = rzCameraPos();
  let dir = normalize(ray);
  // A beam is light in the air BETWEEN the lens and whatever was drawn, so
  // stopping at depth is what occludes it.
  let tMax = min(depth, FAR_CLAMP);
  if (tMax <= 0.01) { return vec4f(0.0); }
  let jitter = hash21(uv * rzResolution());

  // Composited OVER one another, not summed.
  //
  // Three beams converge on the dancer by design, and summing their coverage
  // put the total past 1 exactly where they meet — so the most interesting part
  // of the shot clipped to flat white and lost both the shafts and her legs.
  // Over-compositing is how overlapping lights actually behave: each adds what
  // is left rather than its whole self, so the total approaches 1 and never
  // slams into it.
  var rgbPm = vec3f(0.0);   // premultiplied
  var alpha = 0.0;
  for (var c = 0; c < rzSubjectCount(); c++) {
    let subj = rzSubject(c);
    if (!subj.valid) { continue; }
    let aim = aimPoint(c, subj.root);

    for (var i = 0; i < 3; i++) {
      let side = f32(i) - 1.0;   // -1 left, 0 overhead, +1 right
      var col = COLOR_T;
      if (i == 0) { col = COLOR_L; }
      if (i == 2) { col = COLOR_R; }
      let beam = clamp(beamFor(side, aim, origin, dir, tMax, time, jitter) * DENSITY * 0.06, 0.0, 1.0);
      if (beam > 0.001) {
        rgbPm += col * beam * (1.0 - alpha);
        alpha += beam * (1.0 - alpha);
      }
      // Saturated is saturated: with alpha this close to 1, a third beam's whole
      // march could not move the pixel a code value.
      if (alpha > 0.985) { break; }
    }

    // The pool where the light lands. Read off the pixel's own world position,
    // so it lies on whatever the floor actually is and bends over it.
    if (depth < FAR_CLAMP) {
      let p = rzWorldPos(dir, depth);
      if (abs(p.y - subj.root.y) < FLATNESS) {
        let d = distance(p.xz, aim.xz);
        if (d < POOL_R) {
          let x = 1.0 - d / POOL_R;
          let pool = clamp(x * x * POOL, 0.0, 1.0);
          rgbPm += COLOR_T * pool * (1.0 - alpha);
          alpha += pool * (1.0 - alpha);
        }
      }
    }
  }

  let a = clamp(alpha, 0.0, 1.0);
  if (a <= 0.002) { return vec4f(0.0); }
  // Colour from intensity: light goes white where it is strong and keeps its
  // tint only in the falloff.
  // Un-premultiply for the straight-alpha the mount wants, and only whiten at
  // the very top of the range — pushing to white early is the other half of how
  // the convergence went flat.
  let lit = rgbPm / max(alpha, 1e-4);
  return vec4f(mix(lit, vec3f(1.0), smoothstep(0.8, 1.5, alpha)), a);
}

// @particles 8000

// Snow — the first effect drawn as geometry rather than marched per pixel.
//
// Every flake is one instanced quad, so the cost is the flakes and not the
// screen: eight thousand of these cost less than one fullscreen effect that
// touches every pixel to decide most of them are empty. The old path could not
// have afforded a tenth as many, and the count is the whole difference between
// "it is snowing" and a few dots drifting past.
//
// The volume is FIXED TO THE STAGE, not to the camera.
//
// Following the eye seemed right — weather is everywhere, so keep it where you
// are looking — but it makes the weather a property of the camera rather than of
// the scene, and a camera VMD is the case that proves it wrong: a VMD dollies and
// cuts, and the whole field would lurch after it on every cut. A stage that snows
// is a stage that snows regardless of where you stand to watch it.
//
// The cost is honest: fly the camera outside CENTER ± AREA and the weather is
// behind you. MMD scenes are staged around the origin, so that is a corner rather
// than the common case, and AREA is the dial if a scene needs a bigger stage.

// Tunables.
const FALL = 2.2;        // metres per second, before size weighting
const DRIFT = 0.55;      // sideways wander
const SWIRL = 0.18;      // how tightly the wander curls
const CENTER = vec3f(0.0, 0.0, 0.0);   // the stage the weather falls on
const AREA = 34.0;       // half-width of the volume
const TOP = 46.0;        // ceiling they fall from — well above the frame
const SIZE_MIN = 0.035;
const SIZE_MAX = 0.17;    // a few big ones near the lens, most of them small
const TWINKLE = 0.35;     // how much a flake catches the light as it turns
const SOFT = 0.5;        // softness of the flake's halo, 0..1
const INTENSITY = 3.0;   // HDR brightness — see the note below
const ARMS = 0.55;       // how far the arms reach, 0..1 of the quad
const CORE = 0.16;       // the hub at the centre

// A NOTE ON BRIGHTNESS, because it is the one thing that surprises everyone.
//
// Particles draw INSIDE the scene pass, in HDR, before tone mapping — unlike a
// background or foreground, which composites over the finished frame. So white
// here is not the white you get out: vec3f(1.0) goes through AgX and lands as
// grey. Snow has to be brighter than the paper it is drawn on, which is what
// INTENSITY is for. The upside of the same fact is that the scene's grade and
// exposure apply to the snow, so it belongs to the shot instead of sitting on
// top of it.

fn particleInit(id: u32, seed: f32) -> Particle {
  var p: Particle;
  let r = rzHash13(seed + f32(id) * 0.0173);
  let r2 = rzHash13(seed * 1.77 + f32(id) * 0.0411);
  p.pos = vec3f(CENTER.x + (r.x - 0.5) * AREA * 2.0, r.y * TOP, CENTER.z + (r.z - 0.5) * AREA * 2.0);
  p.size = mix(SIZE_MIN, SIZE_MAX, r2.x);
  // Bigger flakes fall faster, which is what stops the field looking like one
  // sheet sliding down the screen.
  p.vel = vec3f(0.0, -FALL * mix(0.6, 1.4, r2.x), 0.0);
  // Never expires: flakes WRAP at the floor (see step) rather than recycling
  // through the pool, so none of them appears out of nothing in mid-air.
  p.life = 1.0e9;
  p.rot = r2.z * 6.2831853;
  p.seed = seed + f32(id) * 0.0173;
  return p;
}

fn particleStep(p: Particle, dt: f32) -> Particle {
  var q = p;
  // Curl noise is divergence-free, so flakes wander past each other instead of
  // piling into the same line the way a plain sine drift does.
  let w = rzCurlNoise(q.pos * SWIRL + vec3f(0.0, rzTime() * 0.15, 0.0));
  q.pos = q.pos + (q.vel + w * DRIFT) * dt;
  q.rot = q.rot + dt * 0.6;
  // TOROIDAL in x/z as well as y.
  //
  // Wrapping only at the floor meant the volume moved with the camera but its
  // contents did not: orbiting left the old field draining where it was while a
  // new one filled in slowly, a fall-time behind. Folding x and z about the
  // centre too means a flake that leaves one side re-enters on the other in the
  // SAME frame, so the field is always centred and never has to refill. The
  // seam sits AREA away, off to the side and far from what you are looking at.
  let span = AREA * 2.0;
  let rx = q.pos.x - CENTER.x;
  let rz = q.pos.z - CENTER.z;
  q.pos.x = CENTER.x + rx - span * floor(rx / span + 0.5);
  q.pos.z = CENTER.z + rz - span * floor(rz / span + 0.5);
  // And over the top when it reaches the floor, in a freshly chosen column so the
  // same flake never falls down the same line twice.
  if (q.pos.y < 0.0) {
    let h = rzHash13(q.seed + rzTime() * 0.29);
    q.pos = vec3f(CENTER.x + (h.x - 0.5) * span, TOP, CENTER.z + (h.z - 0.5) * span);
  }
  return q;
}

fn sdSegment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

/**
 * A six-armed flake, folded rather than repeated.
 *
 * The obvious way to build one is to loop six times and rotate — which is what
 * the hand-written fullscreen version had to do. Folding the angle into a single
 * 60-degree wedge gets the same six-fold symmetry from ONE arm, so this is three
 * segment tests instead of thirty. That trade is worth spelling out: a particle
 * shader runs on the handful of pixels its own quad covers, not on the screen,
 * so detail here is cheap in a way it never was in a fullscreen march.
 */
fn flake(q: vec2f) -> f32 {
  let k = 1.0471975;                     // 60 degrees
  let a = atan2(q.y, q.x);
  let folded = abs(a - k * floor(a / k + 0.5));
  let r = length(q);
  let p = vec2f(cos(folded), sin(folded)) * r;
  var d = sdSegment(p, vec2f(0.0), vec2f(ARMS, 0.0)) - 0.035;
  d = min(d, sdSegment(p, vec2f(ARMS * 0.45, 0.0), vec2f(ARMS * 0.72, ARMS * 0.30)) - 0.022);
  d = min(d, sdSegment(p, vec2f(ARMS * 0.75, 0.0), vec2f(ARMS * 0.95, ARMS * 0.22)) - 0.018);
  return min(d, r - CORE);
}

fn particleShade(p: Particle, uv: vec2f) -> vec4f {
  let q = (uv - vec2f(0.5)) * 2.0;
  let d = flake(q);
  // The crystal itself, plus a soft bloom of light around it — near flakes read
  // as a shape, distant ones collapse to the halo, which is what snow does.
  let solid = smoothstep(0.04, -0.02, d);
  let halo = rzFalloff(length(q), 1.0) * SOFT * 0.5;
  // No lifetime fade — a wrapped flake never dies, and fading a share of them at
  // any moment is what makes a field look like it is flickering.
  let a = clamp(solid + halo, 0.0, 1.0);
  // Each flake catches the light at its own rate as it tumbles. Snow that all
  // brightens together reads as a flicker; snow that does not sparkle at all
  // reads as paper.
  let twinkle = 1.0 + TWINKLE * sin(rzTime() * (1.3 + p.seed * 2.7) + p.seed * 39.1);
  return vec4f(vec3f(INTENSITY * twinkle), a);
}

// Waveform — mafik's Shadertoy visualiser, ported onto the rzAudio* interface.
// Original: https://www.shadertoy.com/view/XsjGz3 — the structure below follows
// it line for line; the adaptations are named where they happen.
//
// The idea that makes it beautiful: twenty spectrum bands each bend a
// TRAVELLING COSINE into the same coordinate, faster per band, amplitude from
// the band's PEAKINESS (its value against its neighbours' — a second
// difference, so flat noise moves nothing and a beat kicks). The glow is the
// classic 1/|y| falloff around whatever curve all that bending composed.
// Shadertoy feeds a live analyser; here rzAudioBand reads the precomputed
// analysis, which is why an export shows the same picture.
//
// Tunables — edit and ⌘⏎.
const COLOR1 = vec3f(0.0, 0.0, 0.3);   // deep blue, screen left
const COLOR2 = vec3f(0.5, 0.0, 0.0);   // deep red, screen right
const BANDS_N = 20;      // cosines composed — the original's n
const BOUNCE = 0.5;      // how far the music bends the wave. THE size dial:
                         // 1.0 is mafik's full swing, which reaches the frame's
                         // edges on big drops; 0.5 keeps the dance in the middle
                         // of the frame. Scales GEOMETRY only — brightness and
                         // the crisp 1/|y| lines are untouched, which is what
                         // the earlier limiter experiments got wrong.
const GLOW = 200.0;      // the 1/|y| glow's tightness — original's constant
const WAVE_TINT = vec3f(1.9, 1.0, 1.5); // pink-white, r > b > g as mafik had it
const GRAIN = 0.14;      // background texture strength — stands in for iChannel0
                         // against a live analyser; our per-band p95 normalise
                         // runs hotter, so the same maths over-bends
const CALM = 0.10;       // amplitude left when paused, or with no track at all

fn wvHash21(p: vec2f) -> f32 {
  var q = fract(vec3f(p.x, p.y, p.x) * 0.1031);
  q = q + dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}
/** Bilinear value noise — the stand-in for the original's noise texture. */
fn wvNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = wvHash21(i);
  let b = wvHash21(i + vec2f(1.0, 0.0));
  let c = wvHash21(i + vec2f(0.0, 1.0));
  let d = wvHash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
/** The original's audio texture row, as our bands: x 0..1 across the spectrum.
 *  Read raw — the AnalyserNode smoothing already lives in the analysis. */
fn wvSpectrum(x: f32) -> f32 {
  return rzAudioBand(i32(clamp(x, 0.0, 1.0) * f32(rzAudioBandCount() - 1)));
}

fn background(ray: vec3f, uv: vec2f, time: f32) -> vec4f {
  // ── The background, as mafik built it: a blue→red gradient, plus the bass
  // eighth of the spectrum as vertical light columns, darkened, plus grain. ──
  // Paused or trackless goes CALM: the maths below would happily oscillate
  // over a frozen spectrum forever — and with no track at all, the 0.6 seed in
  // the walk fabricates waves out of silence.
  let drive = mix(CALM, 1.0, rzAudioPlaying());
  var bg = mix(COLOR1, COLOR2, uv.x) + vec3f(wvSpectrum(uv.x / 8.0) * drive) - 0.7;
  // Far smoother than the first attempt: at cell size 64 the stand-in noise
  // read as red static, which mafik's texture never was.
  bg += (wvNoise(uv * 9.0) * 0.7 + wvNoise(uv * 23.0) * 0.3) * GRAIN;

  // ── The wave. uv into [-1,1], the original's offsets verbatim. ────────────
  // The wave. uv into [-1,1], the original's offsets verbatim.
  var p = vec2f(-1.0 + 2.0 * uv.x, -1.0 + 2.0 * uv.y);
  p.y += 0.1;
  p.x *= 2.0;

  var prev = 0.0;
  var curr = 0.6;
  var next = wvSpectrum(0.0);
  var wave = vec3f(0.0);
  for (var i = 0; i < BANDS_N; i++) {
    prev = curr;
    curr = next;
    next = wvSpectrum(f32(i + 1) / f32(BANDS_N));
    // Mafik's amplitude, undamped — including the i = 0 line, whose cos(0) is
    // constant: a straight bar displaced by the first band's peakiness squared,
    // the thick centre line that BUMPS with the music. The tempering happens in
    // the analysis instead: bands arrive smoothed with the AnalyserNode's own
    // 0.8, exactly the sluggishness Shadertoy fed him.
    let amp = max(0.0, curr * 2.0 - prev - next) * drive;
    p.y += cos((p.x * 2.0 * f32(i) / f32(BANDS_N) * 10.0 + time * f32(i)) % 6.2831853) * amp * amp * BOUNCE;
    p.x += 0.1;
    let w = abs(1.0 / (GLOW * p.y));
    wave += WAVE_TINT * w * (5.0 / f32(BANDS_N));
  }

  // Full-frame: this IS the background, so alpha is 1 and the scene's own
  // backdrop is replaced, exactly as a Shadertoy canvas would be.
  return vec4f(max(bg + wave, vec3f(0.0)), 1.0);
}

// @anchor 頭
// @anchor 上半身2
// @anchor 左ひじ
// @anchor 右ひじ
// @anchor 左手首
// @anchor 右手首
// @anchor 左ひざ
// @anchor 右ひざ
// @fullres

// Vyke's Dragonbolt — the red fire-lightning of Elden Ring, clinging to a body.
//
// These are ARCS, not lightning. Lightning is a path from somewhere to
// somewhere else and it looks it: straight, spanning, purposeful. An electric
// arc has nowhere to go, so it curves — it crawls around what it is clinging
// to. That is the whole difference between this and a bolt effect, and it is
// built into the geometry rather than tuned in afterwards:
//
//   CRACKLES orbit a joint, on a tilted ring, through less than a third of a
//   turn. CONNECTORS are short bowed pieces of the way between two joints,
//   never the whole span — electricity crawling over a body, not a cable strung
//   between its corners.
//
// Both ORBIT IN DEPTH as well as across the screen, which is what makes them
// look wrapped rather than painted on. Every point of every path carries its
// own distance from the camera, and the half of a ring that swings behind a
// shoulder is hidden by that shoulder. rzProject hands back z in metres on the
// same axis as the depth the mount is given, so the test costs one comparison
// per path — no marching, no 3D distance field.
//
// The depth is derived rather than projected point by point: the ring's screen
// radius is converted to metres once per arc (one extra projection, after the
// bound rejects), and the swing is that radius through the tilt. A tilted ring
// projects to an ellipse and this draws a circle, which is a lie no one can see
// in a jagged filament, and it keeps the whole path in 2D where it is cheap.
//
// Both FORK, off the tangent wherever the branch tears. Eight anchors (head,
// chest, elbows, wrists, knees) plus the hips and the floor point, free from
// rzSubject, cover the whole silhouette. Channels RESTRIKE on a timer rather
// than animating — a path lives for a blink, then a new seed tears a new one
// somewhere else. That flicker is what reads as electricity.
//
// The halo is drawn in two tiers rather than one. A foreground mount composites
// after tone mapping and is clamped to display range, so it never reaches the
// bloom pyramid: every bit of the glow around these arcs has to be in the
// falloff here, and a single radius reads as a flat disc.
//
// Tunables — edit and ⌘⏎.
const CORE_COLOR = vec3f(1.0, 0.78, 0.68);   // the filament — hot, still red
const BODY_COLOR = vec3f(1.0, 0.11, 0.04);   // the body of the arc
const HAZE_COLOR = vec3f(0.52, 0.03, 0.01);  // deep ember, the outer light
const STRIKE_HZ = 5.0;    // new channels per second
const ATTACK = 0.05;      // of a life spent snapping on
const HOLD = 0.55;        // and how much of it is spent at full before dying
const SIZZLE = 9.0;       // flickers per life
const BOLTS = 20;         // channels alive at once — most of them crackles
const CONNECTORS = 6;     // how many of those crawl between two joints
const SEGS = 7;           // jags per arc — enough that the curve stays a curve
const FORK_SEGS = 3;      // and per branch
const CRACKLE_R = 0.024;  // how wide a crackle orbits its joint
const SWEEP_MIN = 0.7;    // and through how much of a turn, in radians
const SWEEP_MAX = 1.9;
const TILT_MIN = 0.45;    // how far the ring leans into the screen: 0 is flat
const TILT_MAX = 1.0;     // on to the frame, 1 is swinging fully through it
const SPAN_MIN = 0.20;    // a connector's length, as a fraction of the joint gap
const SPAN_MAX = 0.38;
const HUG = 0.85;         // how far along its bone a connector may slide
const BOW = 0.5;          // how far a connector bows, relative to JAG
const JAG = 0.016;        // sideways wander — small, or it eats the curve
const CORE_W = 0.0018;    // filament half-width — a hairline, and it stays one
const GLOW_W = 0.0090;    // the tight halo hugging it
const HAZE_W = 0.0500;    // and the wide, faint aura it sits in
const CORE_I = 1.9;
const GLOW_I = 0.90;
const HAZE_I = 0.30;
const FLICKER = 0.40;     // depth of the per-channel brightness flicker
const WOBBLE = 0.35;      // how much the filament writhes while it is alive
const WOBBLE_HZ = 7.0;    // and how fast
const Z_BIAS = 0.02;      // metres of slack, so an arc lying on the skin shows
const Z_FADE = 0.03;      // and how sharply it goes as it passes behind

const TAU = 6.2831853;

fn arcHash(p: vec2f) -> f32 {
  var q = fract(vec3f(p.x, p.y, p.x) * 0.1031);
  q = q + dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

/**
 * The aura around the filament, falling off cubically.
 *
 * The shape is the whole difference between neon and a blob. A linear ramp
 * across the radius fills its disc almost evenly, so a wide one reads as a lit
 * tube; cubed, the same radius stays concentrated on the line and trails away
 * to nothing at its edge — which is what a glass tube full of gas actually does
 * to the air around it. That is what lets the aura be WIDE and faint at once,
 * and a wide faint aura next to a hairline core is the neon look.
 *
 * Bounded, not a 1/r tail: the reject below is derived from HAZE_W, and a glow
 * that never quite reaches zero has no radius to derive one from.
 */
fn arcHalo(dist: f32) -> f32 {
  let t = 1.0 - smoothstep(0.0, HAZE_W, dist);
  return t * t * t;
}

fn arcSeg(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return length(pa - ba * h);
}

/** Ten points on the body: eight declared anchors, then the hips and the floor.
 *  World space — the caller projects, because it also wants the world position
 *  to work out how big a metre is on screen there. w is 0 on a rig without it. */
fn arcWorld(subject: i32, idx: i32) -> vec4f {
  if (idx >= 8) {
    let s = rzSubject(subject);
    if (!s.valid) { return vec4f(0.0); }
    return vec4f(select(s.center, s.root, idx == 9), 1.0);
  }
  let a = rzAnchor(subject, idx);
  return vec4f(a.pos, select(0.0, 1.0, a.valid));
}

const BONE_COUNT = 10;

/**
 * The body as SEGMENTS, not points — which pairs of the ten are joined by limb.
 *
 * Anchors are capped at eight and all eight are spent, but the coverage problem
 * was never the count: ten discrete points leave the forearms, the thighs and
 * the torso bare no matter how many channels orbit the joints, because there is
 * nothing between them to orbit. Naming the segments instead lets a channel sit
 * ANYWHERE along a limb, so eight anchors cover a whole body continuously and
 * more anchors would buy nothing.
 *
 * It also fixes what the connectors were doing. Picking two joints at random
 * drew head-to-knee lines through open air; along a bone, every one of them
 * lies on the body by construction, and the end-hugging that used to paper over
 * that is now just where along the limb it sits.
 *
 * The two lower legs run knee to the FLOOR POINT rather than to an ankle: at
 * eight slots the wrists earn their place more than the ankles do, and knee to
 * floor tracks a shin closely enough while she is standing on it. A lifted leg
 * is the case it approximates worst.
 */
fn arcBone(i: i32) -> vec2<i32> {
  switch i {
    case 0: { return vec2<i32>(1, 0); }   // neck
    case 1: { return vec2<i32>(8, 1); }   // torso
    case 2: { return vec2<i32>(1, 2); }   // upper arm, left
    case 3: { return vec2<i32>(1, 3); }   //            right
    case 4: { return vec2<i32>(2, 4); }   // forearm, left
    case 5: { return vec2<i32>(3, 5); }   //          right
    case 6: { return vec2<i32>(8, 6); }   // thigh, left
    case 7: { return vec2<i32>(8, 7); }   //        right
    case 8: { return vec2<i32>(6, 9); }   // lower leg, left
    default: { return vec2<i32>(7, 9); }  //            right
  }
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // Measure in a square space, or every arc is stretched into an ellipse.
  let p = vec2f(uv.x * aspect, uv.y);

  var core = 0.0;
  var glow = 0.0;
  var haze = 0.0;

  for (var c = 0; c < rzSubjectCount(); c++) {
    let s = rzSubject(c);
    if (!s.valid) { continue; }

    // ── Reject the whole character before touching a single channel ──
    //
    // The two-tier cull below is tight, but every channel had to be SET UP
    // before it could be reached: a hash for its phase, four more for its
    // shape, ten trig calls to sketch it and a projection or two to place it.
    // Twenty-odd of those ran on every pixel of the frame, including the empty
    // corners — which is most of any frame, and was most of the cost.
    //
    // One circle around the character answers all of them at once. Two
    // projections, and a pixel that is nowhere near her is done.
    let bc = rzProject(s.bounds.xyz);
    if (bc.z <= 0.0) { continue; }
    let be = rzProject(s.bounds.xyz + rzCameraUp() * s.bounds.w);
    let br = max(abs(be.y - bc.y), 1e-4);
    let bc2 = vec2f(bc.x * aspect, bc.y);
    // Her silhouette, plus how far past it a channel can stray: a branch may
    // leave a bone by half its length, and an orbit and its aura add their own.
    let bound = br * 1.5 + CRACKLE_R + JAG + HAZE_W;
    if (dot(p - bc2, p - bc2) > bound * bound) { continue; }

    // ── The body, projected once for every channel that will ask ──
    //
    // Each channel used to project the bone it sits on for itself, which is one
    // or two projections apiece and the same joints over and over. Ten points
    // cover every bone, so ten projections cover every channel.
    var pts: array<vec2f, 10>;
    var zs: array<f32, 10>;
    var ok: array<bool, 10>;
    for (var i = 0; i < 10; i++) {
      let wp = arcWorld(c, i);
      let pr = rzProject(wp.xyz);
      pts[i] = vec2f(pr.x * aspect, pr.y);
      zs[i] = pr.z;
      ok[i] = wp.w > 0.5 && pr.z > 0.0;
    }

    // ── How near is this pixel to each LIMB ──
    //
    // The reject above answers "is this pixel anywhere near her" and no more,
    // and it cannot do better: bounds.w is the generous cull sphere, so the
    // circle it gives covers most of the frame whenever she is framed at all.
    // Inside it every channel was still being set up — a hash for its phase,
    // four for its shape, ten trig calls to sketch it — and twenty of those on
    // most of the frame is the whole cost of this effect.
    //
    // Ten segment distances answer it properly. A channel can only reach so far
    // from the bone it lives on, so a pixel beside one arm can throw out every
    // channel on the other arm and both legs for the price of ONE array lookup
    // in the loop below, before any of that setup runs. Ten cheap tests replace
    // most of twenty expensive ones.
    var bd: array<f32, 10>;
    var near = false;
    for (var i = 0; i < BONE_COUNT; i++) {
      let bn = arcBone(i);
      if (!ok[bn.x] || !ok[bn.y]) {
        bd[i] = 1e9;
        continue;
      }
      // Its own longest branch scales with its own length, so a torso claims
      // more room than a forearm and neither is given the other's slack.
      let len = length(pts[bn.y] - pts[bn.x]);
      let reach = CRACKLE_R * 1.25 + JAG + HAZE_W + 0.55 * SPAN_MAX * len;
      bd[i] = arcSeg(p, pts[bn.x], pts[bn.y]) - reach;
      near = near || bd[i] <= 0.0;
    }
    if (!near) { continue; }

    for (var b = 0; b < BOLTS; b++) {
      // Each channel restrikes on its own phase, so they never blink together.
      let phase = time * STRIKE_HZ + f32(b) * 0.317;
      let strike = floor(phase);
      let life = fract(phase);
      let seed = vec2f(strike * 1.7 + f32(b) * 31.7, f32(c) * 11.3 + f32(b) * 5.1);

      // WHICH LIMB this channel lives on — asked FIRST, because the answer is
      // also the cheapest possible rejection. Both shapes below sit on it: a
      // crackle rings some point along it, a connector runs a slice of it.
      let bi = i32(arcHash(seed) * f32(BONE_COUNT) * 0.9999);
      if (bd[bi] > 0.0) { continue; }   // one lookup, and the channel is gone
      let bone = arcBone(bi);
      let e2 = pts[bone.x];
      let f2 = pts[bone.y];
      let ez = zs[bone.x];
      let fz = zs[bone.y];

      // Snap on, HOLD, then die. A plain decay across a life this long reads
      // as a slow fade rather than as an arc that struck and stayed lit; the
      // hold is what lets a channel linger without going sluggish.
      let env = smoothstep(0.0, ATTACK, life) * (1.0 - smoothstep(HOLD, 1.0, life));
      let flick = 1.0 - FLICKER * arcHash(seed + vec2f(life * SIZZLE, 0.0));
      let amp = env * flick;
      if (amp < 0.02) { continue; }

      // The two shapes share one walk below; these are the parameters it needs.
      let curved = b >= CONNECTORS;
      var rad = 0.0;              // curved: orbit radius, on screen
      var a0 = 0.0;               //         from what angle
      var sweep = 0.0;            //         through how much of a turn
      var p0 = vec2f(0.0);        // straight: from here
      var p1 = vec2f(0.0);        //           to here
      var bow = 0.0;              //           bowing this far off the chord
      var z0 = 0.0;               // depth at the head of the run
      var z1 = 0.0;               //           and at its tail
      var anchor = vec2f(0.0);    // what a ring is centred on, on screen
      var anchorZ = 0.0;
      var boneLen = 1.0;          // its bone's length on screen, for the scale

      if (curved) {
        // A crackle: a ring around a point ANYWHERE ALONG the limb. Small
        // radius, partial turn, either handedness — it clings, it does not
        // radiate. Projected from the interpolated world point rather than
        // interpolated between two projections, which is the same thing only
        // for a bone pointed across the frame.
        // Interpolated between the bone's two PROJECTED ends rather than
        // projected from the interpolated world point. Those differ only by
        // what perspective does across the length of one limb, which at the
        // scale of a hairline arc is nothing, and it saves a projection on
        // every channel.
        let tb = arcHash(seed + vec2f(0.9, 3.4));
        anchor = mix(e2, f2, tb);
        anchorZ = mix(ez, fz, tb);
        boneLen = length(f2 - e2);
        z0 = anchorZ;
        z1 = anchorZ;
        rad = CRACKLE_R * (0.55 + 0.7 * arcHash(seed + vec2f(1.1, 8.8)));
        a0 = arcHash(seed + vec2f(5.1, 2.9)) * TAU;
        let turn = SWEEP_MIN + (SWEEP_MAX - SWEEP_MIN) * arcHash(seed + vec2f(2.4, 6.3));
        sweep = select(-turn, turn, arcHash(seed + vec2f(9.2, 0.4)) > 0.5);
      } else {
        // A connector: a SHORT bowed slice OF the limb, not the whole of it.
        let frac = SPAN_MIN + (SPAN_MAX - SPAN_MIN) * arcHash(seed + vec2f(1.1, 8.8));
        // Where along the bone it sits, measured from one end or the other.
        let slide = arcHash(seed + vec2f(4.9, 3.1)) * (1.0 - frac) * HUG;
        let t0 = select(slide, 1.0 - frac - slide, arcHash(seed + vec2f(2.2, 9.6)) > 0.5);
        p0 = mix(e2, f2, t0);
        p1 = mix(e2, f2, t0 + frac);
        // The slice runs along the limb in depth as well as across screen.
        z0 = mix(ez, fz, t0);
        z1 = mix(ez, fz, t0 + frac);
        anchorZ = z0;
        // Signed, so it curves one way instead of wobbling around the chord.
        bow = select(-BOW, BOW, arcHash(seed + vec2f(9.2, 0.4)) > 0.5) * JAG;
      }

      // ── Culling, in two tiers ──
      //
      // Walking the real path costs ten segment tests and ten sines, and a
      // circular bound is a bad fit for something long and thin — worse, it
      // admits every pixel out to the AURA radius, where the wander is far
      // smaller than the distance and nothing about the exact path can be seen.
      // Widening the aura for the neon look therefore cost roughly the square
      // of the widening in walked pixels, which is where the frame rate went.
      //
      // So measure once against a three-piece SKETCH of the shape — both ends,
      // the bulge between them, and the branch as one straight run — and decide
      // from that. Beyond the aura, skip. Inside the aura but outside the
      // filament, shade the aura straight off the sketch: at that distance a
      // wander of JAG is a rounding error on a cubic falloff, and the walk buys
      // nothing. Only pixels near enough to resolve the filament pay for it.
      //
      // The sketch is a capsule rather than a disc, which is the second saving:
      // for a connector it admits about half the pixels the old bound did.
      let run = select(length(p1 - p0), abs(sweep) * rad, curved);
      let fi = 1 + i32(arcHash(seed + vec2f(6.6, 1.3)) * f32(SEGS - 2));
      let tf = f32(fi + 1) / f32(SEGS);
      var mid = (p0 + p1) * 0.5;
      var head = p0;
      var tail = p1;
      var fo = mix(p0, p1, tf);   // where the branch tears, near enough for a cull
      var tang = vec2f(1.0, 0.0);
      if (curved) {
        let am = a0 + sweep * 0.5;
        let af = a0 + sweep * tf;
        head = anchor + vec2f(cos(a0), sin(a0)) * rad;
        tail = anchor + vec2f(cos(a0 + sweep), sin(a0 + sweep)) * rad;
        mid = anchor + vec2f(cos(am), sin(am)) * rad;
        fo = anchor + vec2f(cos(af), sin(af)) * rad;
        tang = vec2f(-sin(af), cos(af)) * sign(sweep);
      } else {
        let dirn = normalize(p1 - p0 + vec2f(1e-5));
        let perp = vec2f(-dirn.y, dirn.x);
        mid = mid + perp * bow;
        fo = fo + perp * (bow * sin(tf * 3.14159265));
        tang = dirn;
      }
      // Same handedness hash the branch itself uses, and its longest reach.
      let fangC = select(-1.1, 1.1, arcHash(seed + vec2f(0.3, 4.4)) > 0.5);
      let fdirC = vec2f(
        tang.x * cos(fangC) - tang.y * sin(fangC),
        tang.x * sin(fangC) + tang.y * cos(fangC)
      );
      let dc = min(
        min(arcSeg(p, head, mid), arcSeg(p, mid, tail)),
        arcSeg(p, fo, fo + fdirC * run * 0.55)
      );
      if (dc > HAZE_W + JAG) { continue; }
      if (dc > GLOW_W + JAG) {
        // Aura only. One depth for the whole shape is enough for something this
        // soft, and it saves working out the metre scale at all.
        let zc = select(mix(z0, z1, 0.5), anchorZ, curved);
        let visC = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, zc);
        haze = max(haze, arcHalo(dc) * amp * visC);
        continue;
      }

      // How far this ring swings toward and away from the camera. The radius is
      // on screen; the bone below says how much of the frame a metre is; the tilt is
      // how much of the ring is pointed through the frame rather than across
      // it. A flat ring never hides, a steep one spends half its sweep behind.
      var zAmp = 0.0;
      var zAxis = 0.0;
      if (curved) {
        let tilt = TILT_MIN + (TILT_MAX - TILT_MIN) * arcHash(seed + vec2f(3.7, 5.5));
        // How many metres a frame-height is HERE, read off the bone the arc
        // is sitting on: its length on screen against its length in the world.
        // That was a second projection per channel when it went through
        // a helper of its own, and the bone already answers it.
        let wl = length(arcWorld(c, bone.y).xyz - arcWorld(c, bone.x).xyz);
        let perFrame = max(boneLen, 1e-5) / max(wl, 1e-4);
        // Capped at the bounding sphere: a camera looking down the up axis
        // makes the metre-to-frame conversion degenerate, and an uncapped
        // swing would then bury or float every arc at once.
        zAmp = min(rad / perFrame * tilt, s.bounds.w);
        zAxis = arcHash(seed + vec2f(8.1, 1.9)) * TAU;
      }

      // fi — where the branch tears off — was chosen by the cull above. Never
      // the first or last jag: a fork at the root reads as two arcs, and one at
      // the tip reads as a fray.
      var forkAt = mid;
      var forkDir = vec2f(1.0, 0.0);
      var forkZ = anchorZ;
      var prev = head;
      var zPrev = select(z0, anchorZ + zAmp * cos(a0 - zAxis), curved);
      // Nearest point on the path, and — the reason this is tracked at all —
      // how far away that point is. One shade, one depth test, per path.
      var d = 1e9;
      var dz = zPrev;

      for (var i = 0; i < SEGS; i++) {
        let t = f32(i + 1) / f32(SEGS);
        // Wander biggest mid-run, so both ends stay where they belong.
        let bulge = sin(t * 3.14159265);
        // The wander is fixed for the life of the channel, so a longer life
        // would sit there as a still picture. This is the one term that moves
        // while it is lit: each jag breathes on its own phase, which is what an
        // arc does when it is hunting for a path.
        let wob = sin(time * WOBBLE_HZ * TAU + arcHash(seed + vec2f(f32(i) * 3.1, 5.5)) * TAU);
        let jit = ((arcHash(seed + vec2f(f32(i) * 9.1, 2.2)) - 0.5) * 2.0 + wob * WOBBLE) * JAG * bulge;
        var next: vec2f;
        var zNext: f32;
        if (curved) {
          // Radially, so the jag roughens the orbit instead of flattening it.
          let ang = a0 + sweep * t;
          next = anchor + vec2f(cos(ang), sin(ang)) * (rad + jit);
          zNext = anchorZ + zAmp * cos(ang - zAxis);
        } else {
          let dirn = normalize(p1 - p0 + vec2f(1e-5));
          next = mix(p0, p1, t) + vec2f(-dirn.y, dirn.x) * (jit + bow * bulge);
          zNext = mix(z0, z1, t);
        }
        let ds = arcSeg(p, prev, next);
        if (ds < d) {
          d = ds;
          dz = (zPrev + zNext) * 0.5;
        }
        if (i == fi) {
          forkAt = next;
          forkDir = normalize(next - prev + vec2f(1e-5));
          forkZ = zNext;
        }
        prev = next;
        zPrev = zNext;
      }

      // The branch: off the tangent, short, thinner, bowed one way so it curls
      // rather than zigzags. Short enough that it takes its depth from where it
      // tore off and does not need one of its own.
      let fang = select(-1.1, 1.1, arcHash(seed + vec2f(0.3, 4.4)) > 0.5);
      let fdir = vec2f(
        forkDir.x * cos(fang) - forkDir.y * sin(fang),
        forkDir.x * sin(fang) + forkDir.y * cos(fang)
      );
      let fperp = vec2f(-fdir.y, fdir.x);
      let fbow = select(-1.0, 1.0, arcHash(seed + vec2f(7.7, 2.1)) > 0.5) * JAG * 0.7;
      let fend = forkAt + fdir * run * (0.25 + 0.30 * arcHash(seed + vec2f(0.7, 6.1)));
      var fa = forkAt;
      var df = 1e9;
      for (var i = 0; i < FORK_SEGS; i++) {
        let t = f32(i + 1) / f32(FORK_SEGS);
        let e = sin(t * 3.14159265);
        let wob = sin(time * WOBBLE_HZ * TAU + arcHash(seed + vec2f(f32(i) * 6.3, 1.4)) * TAU);
        let jit = ((arcHash(seed + vec2f(f32(i) * 4.7, 8.3)) - 0.5) + wob * WOBBLE) * JAG * 0.5 * e;
        let next = mix(forkAt, fend, t) + fperp * (fbow * e + jit);
        df = min(df, arcSeg(p, fa, next));
        fa = next;
      }

      // Hidden where the body is nearer than the arc. Soft, over a few
      // centimetres: a hard test crawls along the silhouette as she turns.
      let visM = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, dz);
      let visF = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, forkZ);
      if (visM + visF <= 0.001) { continue; }

      // BRIGHTEST WINS, rather than summing. Twenty-two channels over ten
      // joints means two or three of them share a limb at any moment, and added
      // light compounds there: the halos merge into one blob and the filament
      // saturates past white in the middle of it. Under a max, an arc crossing
      // another stays as bright as the brighter of the two and no brighter, so
      // each one keeps its own edge and the discharge reads as many thin arcs
      // instead of one lit tube.
      //
      // The branch carries a thinner filament but the same light, so it reads
      // as part of the same discharge rather than as a second, dimmer one.
      core = max(core, (1.0 - smoothstep(0.0, CORE_W, d)) * amp * visM);
      core = max(core, (1.0 - smoothstep(0.0, CORE_W * 0.6, df)) * amp * 0.8 * visF);
      glow = max(glow, (1.0 - smoothstep(0.0, GLOW_W, d)) * amp * visM);
      glow = max(glow, (1.0 - smoothstep(0.0, GLOW_W, df)) * amp * visF);
      haze = max(haze, arcHalo(d) * amp * visM);
      haze = max(haze, arcHalo(df) * amp * visF);
    }
  }

  let heat = core * CORE_I + glow * GLOW_I + haze * HAZE_I;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Colour from intensity: ember in the outer light, red through the body of
  // the arc, and the pale core only where it is genuinely hot — a high
  // threshold, because a red bolt that whites out along its length is an
  // orange one.
  var rgb = mix(HAZE_COLOR, BODY_COLOR, smoothstep(0.03, 0.50, heat));
  rgb = mix(rgb, CORE_COLOR, smoothstep(1.3, 2.4, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

// @fullres

// Summoning Circle — a sigil on the ground under the cast, and the light
// standing on it.
//
// The sigil is a port of nayk's summoningCircle():
//   https://www.shadertoy.com/view/M3KGD3          (nayk, 2024-06-14)
// which itself credits
//   https://glslsandbox.com/e#109235.1
//   https://www.shadertoy.com/view/43V3zG
// The construction below is transcribed rather than reinterpreted — the same
// helpers (lPoly, mPoly, strokeStar, wtrz), the same figures in the same order,
// the same constants. Its shape is three chords struck across a triangle, a
// rimmed ring whose outer stroke breathes on a trapezoidal wave, nested
// triangles and a hexagon, and a hexagram set into a disc at each vertex.
//
// What is NOT the original is where it lives. This draws on the GROUND PLANE
// through rzSubject().root, found by intersecting the view ray with it, so the
// figure lies under the character in the world instead of across the frame.
//
// It is a FOREGROUND mount even though it draws on the ground, and that is
// deliberate. A background mount only survives where the scene did not cover
// the pixel, so a scene with a ground plane would hide the sigil completely.
// Drawn forward and depth-tested by hand, it lies on the floor whether or not
// there is a floor, and her legs cut into it correctly either way.
//
// The one place the port had to change: the original's line widths and feathers
// are constants in a space where the figure fills the frame, so a pixel is
// always far smaller than the thinnest of them. On a ground plane raking away
// toward the horizon a pixel covers a great deal of sigil, and those strokes
// fall below it and break into dashes. So every width and every feather has a
// floor of one measured pixel — metres-per-pixel converted at the point being
// drawn, which holds at any distance, any field of view and any grazing angle.
// Up close nothing is touched and the figure is the original's exactly.
//
// Tunables — edit and ⌘⏎.
const RING_COLOR = vec3f(0.64, 0.34, 1.0);   // the lines — violet
const HOT_COLOR = vec3f(0.92, 0.84, 1.0);    // where they are brightest
const COL_COLOR = vec3f(0.40, 0.07, 0.90);   // deep purple, in the faint light
const SIZE = 1.60;        // sigil radius, in hip heights
const EXTENT = 1.30;      // how far past that radius the FIGURE actually goes.
                          // The rim is at 1.0, but mPoly centres the three
                          // vertex discs ON it and they are 0.2 across, so the
                          // drawing reaches 1.2 — gate any tighter and the
                          // discs come back sliced off, which is exactly what
                          // a rim-radius gate did to them.
const SPIN = 0.05;        // turns per second
const LINE_W = 1.3;       // the one-pixel floor, in pixels
const RING_I = 1.35;      // how hot a line is
const COL_R = 1.05;       // column radius, in hip heights — wide enough to
                          // stand the whole body inside it
const COL_H = 3.0;        // and height, the same
const COL_I = 0.50;
const PULSE = 0.18;       // depth of the breathing brightness
const PULSE_HZ = 0.5;
const Z_BIAS = 0.03;      // metres of slack before the scene occludes it
const Z_FADE = 0.04;

const PI = 3.14159265;
const TAU = 6.2831853;

fn sat(x: f32) -> f32 { return clamp(x, 0.0, 1.0); }

/** p turned by a. GLSL's `p * rot(a)` is a row vector times a column-major
 *  matrix, which comes out as the ordinary counter-clockwise turn. */
fn rot2(p: vec2f, a: f32) -> vec2f {
  let c = cos(a);
  let s = sin(a);
  return vec2f(p.x * c - p.y * s, p.x * s + p.y * c);
}

// The original's signed-distance shorthand: inside is positive.
fn sdR(d: f32, r: f32) -> f32 { return r - d; }
fn sd1(d: f32) -> f32 { return 1.0 - d; }

fn fillA(d: f32, aa: f32) -> f32 { return smoothstep(0.0, aa, d); }

/** Both the width and the feather take a floor of one pixel. Without it the
 *  0.005-wide strokes below vanish wherever the plane rakes away. */
fn strokeA(d: f32, w: f32, aa: f32) -> f32 {
  let ww = max(w, aa * 0.5);
  return 1.0 - smoothstep(ww, ww + aa, abs(d));
}
fn strokeInnerA(d: f32, w: f32, aa: f32) -> f32 { return strokeA(d - w, w, aa); }
fn strokeOuterA(d: f32, w: f32, aa: f32) -> f32 { return strokeA(d + w, w, aa); }

fn lSquare(p: vec2f) -> f32 { let q = abs(p); return max(q.x, q.y); }

/** Distance to a regular n-gon, by folding the angle onto its nearest edge. */
fn lPoly(p: vec2f, n: f32) -> f32 {
  let a = atan2(p.x, p.y) + PI;
  let r = TAU / n;
  return cos(floor(0.5 + a / r) * r - a) * length(p) / cos(r * 0.5);
}

/** Fold the plane into n wedges, each measured from a point s out along its
 *  own axis — how the vertex discs get drawn once and appear three times. */
fn mPoly(p: vec2f, n: f32, s: f32) -> vec2f {
  let r = TAU / n;
  let a = floor(atan2(p.y, p.x) / r) * r + r * 0.5;
  return rot2(vec2f(cos(a), sin(a)) * s - p, -a - PI * 0.5);
}

fn wtri(x: f32) -> f32 { return abs(2.0 * fract(x * 0.5 - 0.25) - 1.0) * 2.0 - 1.0; }
/** Trapezoidal wave — the outer ring's width steps between two values on it. */
fn wtrz(x: f32, w: f32) -> f32 { return clamp(wtri(x * 2.0) * w, -1.0, 1.0); }

/** Two n/2-gons, the second turned or mirrored: for n = 6, a hexagram. */
fn strokeStar(p: vec2f, n: f32, w: f32, aa: f32) -> f32 {
  var l = strokeInnerA(sd1(lPoly(p, n * 0.5)), w, aa);
  let odd = (n - 2.0 * floor(n * 0.5)) != 0.0;
  let p2 = select(rot2(p, TAU / n), vec2f(-p.x, p.y), odd);
  l = l + strokeInnerA(sd1(lPoly(p2, n * 0.5)), w, aa);
  return l;
}

/** nayk's figure, transcribed. p is in sigil radii; 1.0 is the rim. */
fn summoningCircle(p: vec2f, aa: f32) -> f32 {
  var l = 0.0;
  // Three chords struck across the figure — thin bands through the centre,
  // squashed a hundred to one so lSquare reads them as lines.
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 1.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 2.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = l + fillA(sdR(lSquare(rot2(p, PI / 3.0 * 3.5) * vec2f(100.0, 1.0)), 1.0), aa);
  l = sat(l);
  // and cut back out of the triangle, so they read as spokes from its edges.
  l = l - fillA(sd1(lPoly(p, 3.0)), aa);
  l = sat(l);

  let r = atan2(p.y, p.x);
  // The rim: outer stroke breathing between two widths three times around.
  l = l + strokeOuterA(sdR(length(p), 0.98), 0.008 + wtrz(r / TAU * 3.0, 12.0) * 0.005, aa);
  l = l + strokeInnerA(sdR(length(p), 0.95), 0.005, aa);
  // Nested triangles, and the hexagon between them.
  l = l + strokeInnerA(sd1(lPoly(p, 3.0)), 0.01, aa);
  l = l + strokeInnerA(sdR(lPoly(p, 3.0), 0.88), 0.02, aa);
  l = l + strokeInnerA(sdR(lPoly(p, 6.0), 0.53), 0.01, aa);
  let q = mPoly(rot2(p, PI * 0.5), 3.0, 0.5);
  l = l + fillA(sdR(lPoly(q, 3.0), 0.3), aa);
  let q2 = mPoly(rot2(p, PI / 3.0 + PI * 0.5), 3.0, 0.7);
  l = l + fillA(sdR(lPoly(q2, 3.0), 0.1), aa);
  l = l + strokeInnerA(sdR(lPoly(rot2(p, PI), 3.0), 0.5), 0.02, aa);
  l = l + fillA(sdR(length(p), 0.05), aa);

  // A disc at each triangle vertex: punched out of everything above, ringed
  // twice, with a hexagram set into it.
  let q3 = mPoly(rot2(p, PI * 0.5), 3.0, 1.0);
  l = sat(l);
  l = l - fillA(sdR(length(q3), 0.2), aa);
  l = sat(l);
  l = l + strokeInnerA(sdR(length(q3), 0.18), 0.005, aa);
  l = l + strokeInnerA(sdR(length(q3), 0.15), 0.005, aa);
  l = l + strokeStar(rot2(q3, PI) * 7.0, 6.0, 0.1, aa);
  return l;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let ro = rzCameraPos();
  var lines = 0.0;
  var beam = 0.0;

  for (var c = 0; c < rzSubjectCount(); c++) {
    let s = rzSubject(c);
    if (!s.valid) { continue; }
    // Sized off the HIP HEIGHT. bounds.w is a deliberately generous cull
    // sphere, not a fit — sizing off it put the sigil several body heights
    // across, so only ever a fragment of it was on screen. Root to hips is a
    // dependable fraction of any rig's height, and it costs nothing to read.
    let H = max(s.center.y - s.root.y, 0.05);
    let R = H * SIZE;
    // Breathing, per character and out of phase, so a duo does not pulse as one.
    let pulse = 1.0 + PULSE * sin((time * PULSE_HZ + f32(c) * 0.37) * TAU);

    // ── The sigil, on the ground plane through root ──
    if (abs(ray.y) > 1e-4) {
      let t = (s.root.y - ro.y) / ray.y;
      if (t > 0.0) {
        let hit = ro + ray * t;
        let rel = hit.xz - s.root.xz;
        if (dot(rel, rel) < R * R * EXTENT * EXTENT) {
          let at = rzProject(hit);
          // Hidden by anything nearer — her legs, a prop, the lip of a stage.
          // Soft, or the boundary crawls as she moves over it.
          let vis = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, at.z);
          if (vis > 0.001) {
            // One pixel, in sigil radii, HERE — measured rather than assumed,
            // which is what keeps the strokes whole as the plane rakes away and
            // one pixel starts covering a great deal of ground.
            let up = rzProject(hit + rzCameraUp() * 0.25);
            let uvPerM = max(abs(up.y - at.y) * 4.0, 1e-5);
            let aa = max(0.01, LINE_W / (uvPerM * max(res.y, 1.0) * R));
            let sig = summoningCircle(rot2(rel / R, time * SPIN * TAU), aa);
            lines = max(lines, sat(sig) * vis * pulse);
          }
        }
      }
    }

    // ── The column standing on it ──
    //
    // A vertical cylinder, shaded from the ray's CLOSEST APPROACH to its axis
    // rather than marched: for a shape this soft the nearest point carries the
    // whole look, and a march would cost thirty samples to say the same thing.
    let denom = 1.0 - ray.y * ray.y;
    if (denom > 1e-4) {
      let w0 = ro - s.root;
      let tc = (ray.y * w0.y - dot(ray, w0)) / denom;
      if (tc > 0.0) {
        let q = ro + ray * tc;
        let h = (q.y - s.root.y) / (H * COL_H);
        let rad = length(q.xz - s.root.xz) / (H * COL_R);
        if (h > 0.0 && h < 1.0 && rad < 1.0) {
          let qat = rzProject(q);
          let vis = 1.0 - smoothstep(depth + Z_BIAS - Z_FADE, depth + Z_BIAS + Z_FADE, qat.z);
          // Squared across the radius rather than cubed: a shaft of light
          // still, but one that carries out to its edge instead of collapsing
          // onto its axis — a cubic falloff is down to an eighth at the halfway
          // mark, which leaves the body standing outside its own light. Fading
          // out at the top, and in off the ground so it does not end in a hard
          // disc where it meets the sigil.
          let radial = 1.0 - smoothstep(0.0, 1.0, rad);
          let vert = (1.0 - h) * smoothstep(0.0, 0.12, h);
          beam = max(beam, radial * radial * vert * vis * pulse);
        }
      }
    }
  }

  let heat = lines * RING_I + beam * COL_I;
  if (heat <= 0.004) { return vec4f(0.0); }
  // Deep purple in the faint light, violet through the strokes, and a pale
  // lilac only where they are hottest.
  var rgb = mix(COL_COLOR, RING_COLOR, smoothstep(0.05, 0.6, heat));
  rgb = mix(rgb, HOT_COLOR, smoothstep(1.0, 1.9, heat));
  return vec4f(rgb, clamp(heat, 0.0, 1.0));
}

// @anchor 頭
// @anchor 上半身2
// @anchor 左ひじ
// @anchor 右ひじ
// @anchor 左手首
// @anchor 右手首
// @fullres

// Immolation — the upper body alight, after Elden Ring's flame incantations.
//
// The obvious way to build this is one plume per emitter: pick a dozen points
// on the body, give each a rising puff of noise, add them up. It costs a noise
// field per emitter per pixel and it still looks like a dozen separate fires.
//
// This does it the other way round. Six UPPER-BODY segments — neck, torso, both
// upper arms, both forearms — are joined from the anchors, and the distance to
// the nearest of them is a cheap silhouette field of her top half: one number
// that already knows where she is and which way her arm points. The fire is a
// single noise field, evaluated once per pixel, thresholded against it. One
// evaluation lights the whole figure, and because the field is continuous the
// flames wrap her instead of sitting in tufts.
//
// Three things make it read as fire rather than as orange fog, and the first
// two are the ones a particle system could not do at all:
//
//   DOMAIN WARP. The noise is sampled at coordinates displaced by another
//   noise. Straight fbm gives billows; warped fbm gives the curling licks and
//   hooks that flame actually makes, which is the whole texture of the
//   reference.
//
//   ANISOTROPY, twice over. The field is measured with up cheap and down
//   expensive, so it dilates upward and nothing hangs beneath her. And the
//   noise itself is sampled on a lattice stretched vertically, so its cells are
//   tall — flame structures are tall and thin, never round.
//
//   A HIGH FLOOR. Most of the field is cut away entirely. Fire is mostly gaps;
//   a threshold low enough to keep every wisp is a threshold that fills the
//   frame, which is what a soft falloff wants to do if you let it.
//
// Weighted to the upper body by height, so it erupts off the shoulders and head
// and dies out around the waist. And deliberately faint where it crosses her —
// at the silhouette you look through the whole depth of the fire at once, and
// that is where it belongs; drawn at full strength over her body it just hides
// the character it is supposed to be burning.
//
// Full resolution. Billowing noise upsamples for free and this ran at half for
// exactly that reason, but filaments do not: at half res the fine field that
// splits the tongues is reconstructed by a bilinear blend, and what should be
// a thread of flame arrives as a smear. It shows worst on the faint fire
// crossing her body, where there is no bright structure to hide it.
//
// Tunables — edit and ⌘⏎.
const SMOKE_COLOR = vec3f(0.42, 0.02, 0.01);  // the cool tips — crimson, not brown
const RED_COLOR = vec3f(0.92, 0.13, 0.02);
const ORANGE_COLOR = vec3f(1.0, 0.45, 0.05);
const HOT_COLOR = vec3f(1.0, 0.90, 0.52);     // the hearts of the tongues
const LIMB = 0.08;      // limb half-thickness, in hip heights
const REACH = 0.26;     // how far flames reach SIDEWAYS, the same
const UP_K = 0.24;      // upward distance counts this much: lower climbs higher
const DOWN_K = 3.0;     // and downward this much: higher keeps fire off the floor
const FX = 13.0;        // noise cells across a hip height
const FY = 5.5;         // and up it — fewer, so the cells are tall
const WARP = 0.60;      // how far the field displaces its own lookup
const RISE = 2.8;       // hip heights per second the tongues climb
const ROIL = 0.80;      // how much the noise breaks the falloff into tongues
const FLOOR = 0.46;     // threshold — most of the field is cut away
const WISP = 0.55;      // depth of the fine filament breakup
const WISP_F = 2.8;     // and how fine it is, relative to the main field
const INSIDE = 0.22;    // OPACITY of fire over her body, relative to off her
                        // edge — opacity only, never brightness
const LOW = -0.10;      // height where fire dies, in hip heights off the hips
const HIGH = 0.45;      // and where it is fully lit
const FLICKER = 0.14;
const FLICKER_HZ = 6.0;

const BONE_COUNT = 6;

/** Which pairs of the points are joined by limb. Upper body only — the legs
 *  carry no fire, so their anchors are not even declared. */
fn fireBone(i: i32) -> vec2<i32> {
  switch i {
    case 0: { return vec2<i32>(1, 0); }   // neck
    case 1: { return vec2<i32>(6, 1); }   // torso, hips to chest
    case 2: { return vec2<i32>(1, 2); }   // upper arm, left
    case 3: { return vec2<i32>(1, 3); }   //            right
    case 4: { return vec2<i32>(2, 4); }   // forearm, left
    default: { return vec2<i32>(3, 5); }  //          right
  }
}

/** Six declared anchors, then the hips from rzSubject. */
fn fireWorld(subject: i32, idx: i32) -> vec4f {
  if (idx >= 6) {
    let s = rzSubject(subject);
    if (!s.valid) { return vec4f(0.0); }
    return vec4f(s.center, 1.0);
  }
  let a = rzAnchor(subject, idx);
  return vec4f(a.pos, select(0.0, 1.0, a.valid));
}

fn fireHash(p: vec2f) -> f32 {
  var q = fract(vec3f(p.x, p.y, p.x) * 0.1031);
  q = q + dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

fn fireNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(fireHash(i), fireHash(i + vec2f(1.0, 0.0)), u.x),
    mix(fireHash(i + vec2f(0.0, 1.0)), fireHash(i + vec2f(1.0, 1.0)), u.x),
    u.y
  );
}

/** Four octaves. Fire has detail at every scale it is worth paying for; three
 *  reads as cloud, five is past what a half-res target can show. */
fn fireFbm(p: vec2f) -> f32 {
  var sum = 0.0;
  var amp = 0.5;
  var q = p;
  for (var i = 0; i < 4; i++) {
    sum = sum + amp * fireNoise(q);
    q = q * 2.07 + vec2f(1.7, 9.2);
    amp = amp * 0.5;
  }
  return sum / 0.9375;
}

/**
 * Turbulence — the same octaves folded through abs(2n - 1).
 *
 * Plain fbm is smooth everywhere, so thresholding it gives rounded blobs with
 * soft shoulders. Folding each octave puts a CREASE wherever the noise crosses
 * its midpoint, and the creases are thin, branching and continuous across
 * scales. Inverted, they are exactly the filigree that runs through real flame:
 * thread-thin bright lines curling through the body of the fire, which is what
 * the reference has everywhere and smooth noise cannot produce at any
 * frequency. Two octaves — the third is below what survives the threshold.
 */
fn fireRidge(p: vec2f) -> f32 {
  var sum = 0.0;
  var amp = 0.6;
  var q = p;
  for (var i = 0; i < 2; i++) {
    sum = sum + amp * abs(2.0 * fireNoise(q) - 1.0);
    q = q * 2.11 + vec2f(4.3, 2.9);
    amp = amp * 0.5;
  }
  return 1.0 - sum / 0.9;
}

/** The vector from the nearest point of a segment to p — the direction matters
 *  here, because up and down are not the same distance to a flame. */
fn fireDelta(p: vec2f, a: vec2f, b: vec2f) -> vec2f {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
  return pa - ba * h;
}

fn foreground(ray: vec3f, uv: vec2f, time: f32, depth: f32) -> vec4f {
  let res = rzResolution();
  let aspect = res.x / max(res.y, 1.0);
  // A square space, or the flames lean with the frame's aspect.
  let p = vec2f(uv.x * aspect, uv.y);

  var heat = 0.0;
  var cover = 1.0;

  for (var c = 0; c < rzSubjectCount(); c++) {
    let s = rzSubject(c);
    if (!s.valid) { continue; }

    // How big this character is ON SCREEN, so every length below can be written
    // in hip heights and hold as the camera pushes in or pulls out.
    //
    // Measured from the HIPS, not the bounding sphere: bounds.w is a
    // deliberately generous cull radius rather than a fit, and reaching a
    // fraction of it in every direction is what filled the frame with fire.
    let H = max(s.center.y - s.root.y, 0.05);
    let mid = rzProject(s.center);
    if (mid.z <= 0.0) { continue; }
    let mid2 = vec2f(mid.x * aspect, mid.y);
    // WHICH WAY IS UP, on screen, for this character.
    //
    // Everything below — the anisotropy, the height weighting, the direction
    // the noise scrolls — is measured against this rather than against the
    // frame's own +y. Screen up is only world up when the camera is level, so
    // measuring against it makes flames lean with the camera: tilt and they
    // tilt with you, orbit under her and they climb out of frame sideways.
    // A world-up vector projected from her hips gives both the direction AND
    // its foreshortened length, so fire correctly looks shorter from above.
    let upW = rzProject(s.center + vec3f(0.0, H, 0.0));
    let upV = vec2f(upW.x * aspect, upW.y) - mid2;
    // Looking straight down the up axis this collapses; fall back to the
    // camera's own up for scale so the fire keeps a sane size rather than
    // exploding as the divisor goes to nothing.
    let camE = rzProject(s.center + rzCameraUp() * H);
    let srCam = max(abs(camE.y - mid.y), 1e-4);
    let sr = max(length(upV), srCam * 0.35);
    let upDir = select(normalize(upV), vec2f(0.0, 1.0), length(upV) < 1e-5);
    let sideDir = vec2f(-upDir.y, upDir.x);
    // Bounding reject — and it has to be DERIVED, not guessed.
    //
    // A guessed radius clips the fire at the top of its own circle, and near
    // the apex a circle is flat to within a pixel across a wide span, so the
    // failure does not look like a circle at all: it looks like someone drew a
    // straight line across the tallest flames. The reach is: however far the
    // furthest limb can be from the hips, plus however far fire climbs above a
    // limb. The first is the bounding SPHERE, which is generous precisely
    // because it already covers a raised arm; the second falls out of the
    // anisotropy, since a pixel LIMB + REACH away along up is at UP_K times
    // that distance in the field.
    let off = length(s.bounds.xyz - s.center) / H;
    let cull = sr * (off + s.bounds.w / H + (REACH + LIMB) / UP_K);
    if (dot(p - mid2, p - mid2) > cull * cull) { continue; }

    // Height off the hips ALONG WORLD UP, in hip heights — the upper-body
    // weight, which must not slide around her as the camera swings.
    let rel = p - mid2;
    let ly = dot(rel, upDir) / sr;
    let lx = dot(rel, sideDir) / sr;
    let tall = smoothstep(LOW, HIGH, ly);
    if (tall <= 0.001) { continue; }

    // Her top half, as six segments on screen.
    var pts: array<vec2f, 7>;
    var good: array<bool, 7>;
    for (var i = 0; i < 7; i++) {
      let w = fireWorld(c, i);
      let pr = rzProject(w.xyz);
      pts[i] = vec2f(pr.x * aspect, pr.y);
      good[i] = w.w > 0.5 && pr.z > 0.0;
    }

    // Nearest limb, measured with up cheap and down expensive.
    var d = 1e9;
    for (var i = 0; i < BONE_COUNT; i++) {
      let bone = fireBone(i);
      if (!good[bone.x] || !good[bone.y]) { continue; }
      let v = fireDelta(p, pts[bone.x], pts[bone.y]);
      // Split along world up and across it, then charge each differently.
      let vy = dot(v, upDir);
      let vx = dot(v, sideDir);
      let ky = select(vy * DOWN_K, vy * UP_K, vy > 0.0);
      d = min(d, length(vec2f(vx, ky)));
    }
    if (d > 1e8) { continue; }

    // Hip heights from the nearest limb surface, so the numbers above are
    // readable and the fire is the same size on a chibi and on a tall model.
    let t = 1.0 - clamp((d / sr - LIMB) / REACH, 0.0, 1.0);
    if (t <= 0.0) { continue; }

    // ONE noise field for the whole body, in body-local coordinates so it does
    // not swim across her when the camera moves, on a lattice stretched
    // vertically so its cells are tall, climbing with time.
    // The lattice stands upright in the WORLD, so the tall cells stay tall and
    // the scroll climbs the way she does, whatever the camera is doing.
    let q = vec2f(lx * FX, ly * FY) + vec2f(0.0, -time * RISE * FY);
    // Warped by itself, TWICE. One stage of displacement bends the field and
    // gives licks; feeding that stage into a second, finer one folds the bends
    // back over themselves, and folded bends are the curls and hooks — the
    // closed loops of flame in the reference that a single warp never makes,
    // because a single warp can only ever push the field sideways.
    let w1 = vec2f(fireFbm(q * 0.34), fireFbm(q * 0.34 + vec2f(5.2, 1.3))) - 0.5;
    let w2 = vec2f(fireFbm(q * 0.95 + w1), fireFbm(q * 0.95 + w1 + vec2f(3.1, 7.7))) - 0.5;
    let n = fireFbm(q + (w1 * 1.5 + w2 * 0.8) * WARP * FY);
    let flick = 1.0 - FLICKER * fireNoise(vec2f(time * FLICKER_HZ + f32(c) * 3.7, 0.5));

    // The falloff says how far fire COULD reach here; the noise carves that
    // into tongues, and the floor cuts the gaps between them clean away.
    var h = clamp((t * tall * (1.0 - ROIL + ROIL * 2.0 * n) - FLOOR) / (1.0 - FLOOR), 0.0, 1.0);
    // The filigree, laid over the tongues and carried by the same warp so it
    // curls with them rather than sliding across them.
    let fine = fireRidge(q * WISP_F + w1 * WARP * FY + vec2f(0.0, -time * RISE * FY * 1.5));
    h = h * (1.0 - WISP + WISP * 2.0 * fine) * flick;

    // Fainter where it crosses her — but by OPACITY, not by strength. Scaling
    // the heat slid every pixel down the colour ramp, so fire over her body
    // came out as the dark smoky end of it: a brown wash with no structure,
    // which is what made it read as a blur rather than as flame. The shape and
    // the colour are now decided at full strength and only the coverage is
    // pulled back, so the tongues stay tongues and you see her through them.
    let covered = 1.0 - smoothstep(H * 1.2, H * 1.8, abs(depth - mid.z));
    if (h > heat) {
      heat = h;
      cover = mix(1.0, INSIDE, covered);
    }
  }

  if (heat <= 0.004) { return vec4f(0.0); }
  // A WIDE red plateau before the orange starts. In the reference the yellow
  // hearts are small and everything around them is deep red for a long way out;
  // ramping straight from red to orange makes the whole fire read as orange,
  // which is the difference between a bonfire and this.
  var rgb = mix(SMOKE_COLOR, RED_COLOR, smoothstep(0.02, 0.20, heat));
  rgb = mix(rgb, ORANGE_COLOR, smoothstep(0.36, 0.68, heat));
  rgb = mix(rgb, HOT_COLOR, smoothstep(0.78, 0.97, heat));
  // Never fully opaque: flame is something you see through, and the character
  // behind it has to stay readable.
  return vec4f(rgb, smoothstep(0.03, 0.45, heat) * 0.88 * cover);
}
